const NOMES_ICONES = Object.keys(ICONES_LUCIDE);
function svgIcone(nome, classe, extra) {
  const n = ICONES_LUCIDE[nome] ? nome : 'sparkles';
  return `<svg data-icone="${n}" class="dia-ic${classe ? ' ' + classe : ''}" viewBox="0 0 24 24" width="1.25em" height="1.25em" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"${extra || ''}>${ICONES_LUCIDE[n]}</svg>`;
}
function iconeValido(nome, reserva) {
  const n = String(nome || '').toLowerCase().trim();
  return ICONES_LUCIDE[n] ? n : (reserva || 'sparkles');
}
// <i data-icone="truck" class="x"></i> (ou <span>) -> <svg ...> com as mesmas classes e estilo
function injectarIcones(html) {
  return String(html || '').replace(/<(i|span)\b([^>]*?)\sdata-icone=["']([a-z0-9-]+)["']([^>]*)>\s*<\/\1>/gi, (t, tag, a1, nome, a2) => {
    const attrs = (a1 + ' ' + a2);
    const classe = (/\sclass=["']([^"']*)["']/i.exec(' ' + attrs) || [])[1] || '';
    const estilo = (/\sstyle=["']([^"']*)["']/i.exec(' ' + attrs) || [])[1] || '';
    const titulo = (/\saria-label=["']([^"']*)["']/i.exec(' ' + attrs) || [])[1] || '';
    return svgIcone(iconeValido(nome), classe, (estilo ? ` style="${estilo}"` : '') + (titulo ? ` role="img" aria-label="${titulo}"` : ''));
  });
}
const INSTRUCAO_ICONES = `\nÍCONES PROFISSIONAIS (obrigatório): nunca desenhes ícones em SVG à mão nem uses emojis como ícones. Para cada ícone escreve só <i data-icone="NOME"></i> (podes pôr class e style, ex: <i data-icone="truck" class="icone"></i>) - o sistema troca pelo ícone profissional certo, em SVG de linha que herda a cor (currentColor) e mede 1.25em (muda com font-size ou width/height no CSS, ex: .icone{width:28px;height:28px}). Nomes disponíveis: ${NOMES_ICONES.join(', ')}. Logótipos, ilustrações, formas decorativas e padrões continuam a poder ser SVG teu.`;

