// ---- CSS base de todos os templates (as cores e letras vêm das fichas) ----
const TPL_CSS = `
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%;overflow-x:clip}
body{margin:0;background:var(--dia-fundo);color:var(--dia-texto);font-family:var(--dia-fonte-texto),system-ui,sans-serif;font-size:16.5px;line-height:1.65;-webkit-font-smoothing:antialiased;overflow-x:hidden}
img,svg{display:block;max-width:100%}
a{color:inherit}
p{margin:0}
h1,h2,h3,h4{font-family:var(--dia-fonte-titulos),serif;line-height:1.07;letter-spacing:var(--t-titulo-espaco);font-weight:var(--t-titulo-peso);text-transform:var(--t-titulo-caixa);margin:0;text-wrap:balance}
em.dest{font-style:var(--t-dest-estilo);color:var(--t-dest-cor);font-family:var(--t-dest-fonte)}
.w{width:min(calc(100% - 2*clamp(18px,4.5vw,44px)),var(--t-max));margin-inline:auto}
.s{padding:var(--t-espaco) 0;position:relative}
.s.alt{background:var(--t-fundo2)}
.s.escura{background:var(--t-escuro);color:var(--t-escuro-texto);--dia-texto:var(--t-escuro-texto);--dia-texto-suave:var(--t-escuro-suave);--dia-borda:rgba(255,255,255,.12);--dia-superficie:rgba(255,255,255,.05)}
.s.cor{background:var(--dia-primaria);color:var(--dia-primaria-texto);--dia-texto:var(--dia-primaria-texto);--dia-texto-suave:color-mix(in srgb,var(--dia-primaria-texto) 78%,transparent);--dia-borda:color-mix(in srgb,var(--dia-primaria-texto) 22%,transparent)}
.etq{display:inline-flex;align-items:center;gap:10px;font-size:12.5px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--t-etq-cor)}
.etq::before{content:"";width:24px;height:2px;border-radius:2px;background:currentColor}
.s.cor .etq,.s.escura .etq{color:inherit;opacity:.85}
.s-cab{max-width:760px;margin-bottom:clamp(34px,5vw,60px)}
.s-cab.centro{text-align:center;margin-inline:auto}.s-cab.centro .etq{justify-content:center}
.s-cab h2{font-size:clamp(30px,4.6vw,54px);margin:16px 0 14px}
.s-cab p{color:var(--dia-texto-suave);font-size:clamp(16px,1.6vw,18.5px);max-width:640px}
.s-cab.centro p{margin-inline:auto}
.s-cab-linha{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;flex-wrap:wrap;margin-bottom:clamp(30px,4vw,52px)}
.s-cab-linha .s-cab{margin-bottom:0}
.lead{font-size:clamp(17px,1.8vw,20px);color:var(--dia-texto-suave);line-height:1.6}
.suave{color:var(--dia-texto-suave)}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:52px;padding:0 26px;border-radius:var(--t-raio-btn);font-weight:700;font-size:15.5px;text-decoration:none;border:0;cursor:pointer;transition:transform .2s,box-shadow .2s,background .2s,color .2s;white-space:nowrap}
.btn .dia-ic{width:18px;height:18px}
.btn-p{background:var(--dia-primaria);color:var(--dia-primaria-texto);box-shadow:0 14px 30px -16px color-mix(in srgb,var(--dia-primaria) 85%,transparent)}
.btn-p:hover{transform:translateY(-2px);box-shadow:0 20px 36px -16px color-mix(in srgb,var(--dia-primaria) 90%,transparent)}
.btn-s{background:transparent;color:inherit;box-shadow:inset 0 0 0 1.5px color-mix(in srgb,currentColor 35%,transparent)}
.btn-s:hover{box-shadow:inset 0 0 0 1.5px currentColor}
.s.cor .btn-p{background:var(--dia-primaria-texto);color:var(--dia-primaria)}
.btns{display:flex;flex-wrap:wrap;gap:12px;align-items:center}
.lnk{display:inline-flex;align-items:center;gap:8px;font-weight:700;text-decoration:none;color:var(--t-etq-cor)}
.lnk .dia-ic{width:17px;height:17px;transition:transform .2s}.lnk:hover .dia-ic{transform:translateX(4px)}
.cartao{background:var(--dia-superficie);border:var(--t-borda) solid var(--dia-borda);border-radius:var(--dia-raio);padding:clamp(22px,3vw,34px);box-shadow:var(--t-sombra);transition:transform .25s,box-shadow .25s,border-color .25s}
a.cartao{text-decoration:none;display:block}
.cartao.mexe:hover{transform:translateY(-4px);border-color:color-mix(in srgb,var(--dia-primaria) 45%,var(--dia-borda))}
.icx{width:54px;height:54px;flex:0 0 54px;border-radius:calc(var(--dia-raio)*.7);display:grid;place-items:center;background:color-mix(in srgb,var(--dia-primaria) 13%,transparent);color:var(--t-etq-cor)}
.icx .dia-ic{width:25px;height:25px}
.s.cor .icx{background:color-mix(in srgb,var(--dia-primaria-texto) 16%,transparent);color:inherit}
.grid{display:grid;gap:clamp(16px,2.4vw,28px)}
.g2{grid-template-columns:repeat(auto-fit,minmax(min(100%,420px),1fr))}
.g3{grid-template-columns:repeat(auto-fit,minmax(min(100%,290px),1fr))}
.g4{grid-template-columns:repeat(auto-fit,minmax(min(100%,230px),1fr))}
.duas{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(28px,6vw,90px);align-items:center}
.foto{position:relative;overflow:hidden;border-radius:var(--t-raio-foto);background:color-mix(in srgb,var(--dia-primaria) 12%,var(--dia-superficie))}
.foto img{width:100%;height:100%;object-fit:cover}
.arte{position:relative;width:100%;height:100%;min-height:220px;display:grid;place-items:center;overflow:hidden;background:radial-gradient(120% 90% at 20% 15%,color-mix(in srgb,var(--dia-primaria) 55%,transparent),transparent 60%),radial-gradient(90% 80% at 85% 90%,color-mix(in srgb,var(--t-destaque) 55%,transparent),transparent 60%),color-mix(in srgb,var(--dia-primaria) 16%,var(--dia-superficie));color:color-mix(in srgb,var(--dia-primaria) 70%,var(--dia-texto))}
.arte::after{content:"";position:absolute;inset:0;background-image:radial-gradient(color-mix(in srgb,var(--dia-texto) 12%,transparent) 1px,transparent 1px);background-size:18px 18px;mask-image:linear-gradient(135deg,#000,transparent 70%)}
.arte .dia-ic{width:clamp(56px,9vw,96px);height:clamp(56px,9vw,96px);stroke-width:1.3;opacity:.85;position:relative;z-index:1}
.chip{display:inline-flex;align-items:center;gap:8px;padding:8px 14px;border-radius:999px;background:var(--dia-superficie);border:1px solid var(--dia-borda);font-size:13.5px;font-weight:700;box-shadow:0 12px 30px -18px rgba(0,0,0,.35)}
.chip .dia-ic{width:16px;height:16px;color:var(--t-etq-cor)}
.estrelas{display:flex;gap:3px;color:#F5A623}.estrelas .dia-ic{width:16px;height:16px;fill:currentColor}
html.js .rv{opacity:0;transform:translateY(22px);transition:opacity .8s cubic-bezier(.2,.7,.2,1),transform .8s cubic-bezier(.2,.7,.2,1)}
html.js .rv.on{opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){html.js .rv{opacity:1;transform:none;transition:none}*{scroll-behavior:auto}}
/* ---- cabeçalho ---- */
.cab{position:sticky;top:0;z-index:50;background:color-mix(in srgb,var(--t-cab-fundo) 92%,transparent);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);color:var(--t-cab-texto);border-bottom:1px solid var(--t-cab-borda)}
.cab-in{display:flex;align-items:center;gap:22px;min-height:76px}
.marca{display:inline-flex;align-items:center;gap:10px;text-decoration:none;font-family:var(--dia-fonte-titulos),serif;font-weight:800;font-size:21px;letter-spacing:-.02em;white-space:nowrap}
.marca img{max-height:44px;width:auto}
.marca i{width:34px;height:34px;border-radius:calc(var(--dia-raio)*.6);background:var(--dia-primaria);color:var(--dia-primaria-texto);display:grid;place-items:center;font-style:normal;font-size:17px;font-weight:800}
.nav{display:flex;align-items:center;gap:clamp(14px,2vw,30px);margin-left:auto}
.nav a{text-decoration:none;font-weight:600;font-size:15px;opacity:.82;position:relative;padding:6px 0;transition:opacity .2s}
.nav a:hover,.nav a[aria-current="page"]{opacity:1}
.nav a[aria-current="page"]::after{content:"";position:absolute;left:0;right:0;bottom:-2px;height:2px;border-radius:2px;background:var(--dia-primaria)}
.cab-acoes{display:flex;align-items:center;gap:10px}
.cab .btn{min-height:44px;padding:0 20px;font-size:14.5px}
.cab-carrinho{position:relative;width:44px;height:44px;border-radius:50%;display:grid;place-items:center;border:1px solid var(--t-cab-borda);background:transparent;color:inherit;cursor:pointer}
.cab-carrinho .dia-ic{width:20px;height:20px}
.cab-carrinho span{position:absolute;top:-4px;right:-4px;min-width:20px;height:20px;padding:0 5px;border-radius:999px;background:var(--dia-primaria);color:var(--dia-primaria-texto);font-size:11px;font-weight:800;display:grid;place-items:center}
.burger{display:none;width:44px;height:44px;border-radius:12px;border:1px solid var(--t-cab-borda);background:transparent;color:inherit;cursor:pointer;place-items:center}
.burger .dia-ic{width:22px;height:22px}.burger .ic-fechar,.cab.aberto .burger .ic-abrir{display:none}.cab.aberto .burger .ic-fechar{display:block}
.cab-barra{background:var(--t-escuro);color:var(--t-escuro-texto);font-size:13px}
.cab-barra .w{display:flex;gap:22px;align-items:center;min-height:38px;flex-wrap:wrap}
.cab-barra span{display:inline-flex;align-items:center;gap:7px;opacity:.85}.cab-barra .dia-ic{width:14px;height:14px}
.cab-barra span:last-child{margin-left:auto}
.cab-centrado .cab-in{flex-direction:column;gap:6px;padding:16px 0 10px;min-height:0}
.cab-centrado .nav{margin:0;justify-content:center}
.cab-centrado .cab-acoes{position:absolute;right:clamp(18px,4.5vw,44px);top:20px}
.cab-pilula{background:transparent;border:0;backdrop-filter:none;-webkit-backdrop-filter:none;padding-top:14px}
.cab-pilula .cab-in{background:color-mix(in srgb,var(--t-cab-fundo) 88%,transparent);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);border:1px solid var(--t-cab-borda);border-radius:999px;padding:0 10px 0 22px;min-height:66px;box-shadow:0 18px 40px -26px rgba(0,0,0,.45)}
@media (max-width:900px){
  .burger{display:grid}
  .cab,.cab-pilula .cab-in{backdrop-filter:none;-webkit-backdrop-filter:none}
  .cab{background:var(--t-cab-fundo)}.cab-pilula{background:transparent}.cab-pilula .cab-in{background:var(--t-cab-fundo)}
  .nav{position:fixed;inset:0;z-index:60;flex-direction:column;align-items:flex-start;justify-content:center;gap:8px;padding:90px clamp(24px,8vw,60px) 40px;background:var(--t-cab-fundo);color:var(--t-cab-texto);transform:translateY(-102%);visibility:hidden;transition:transform .45s cubic-bezier(.7,0,.2,1),visibility 0s .45s;margin:0}
  .cab.aberto .nav{visibility:visible;transition:transform .45s cubic-bezier(.7,0,.2,1)}
  .nav a{font-family:var(--dia-fonte-titulos),serif;font-size:clamp(28px,8vw,40px);font-weight:700;opacity:1}
  .nav a[aria-current="page"]::after{display:none}.nav a[aria-current="page"]{color:var(--dia-primaria)}
  .cab.aberto .nav{transform:none}
  .cab.aberto .burger{position:fixed;top:16px;right:clamp(18px,4.5vw,44px);z-index:70}
  .cab-in{gap:12px}.cab-acoes{margin-left:auto}.cab .cab-acoes .btn{display:none}
  .cab-centrado .cab-in{flex-direction:row;padding:0;min-height:72px}.cab-centrado .cab-acoes{position:static}
  .cab-barra span:not(:first-child){display:none}
}
/* ---- rodapé ---- */
.rod{background:var(--t-rod-fundo);color:var(--t-rod-texto);padding:clamp(56px,8vw,96px) 0 28px;--dia-texto-suave:color-mix(in srgb,var(--t-rod-texto) 66%,transparent);--dia-borda:color-mix(in srgb,var(--t-rod-texto) 14%,transparent)}
.rod-grelha{display:grid;grid-template-columns:1.5fr repeat(3,1fr);gap:clamp(28px,4vw,56px)}
.rod h4{font-size:13px;letter-spacing:.14em;text-transform:uppercase;font-family:var(--dia-fonte-texto);font-weight:800;margin-bottom:16px;opacity:.9}
.rod a{text-decoration:none;color:var(--dia-texto-suave);transition:color .2s}.rod a:hover{color:var(--t-rod-texto)}
.rod ul{list-style:none;margin:0;padding:0;display:grid;gap:10px}
.rod li{display:flex;gap:9px;align-items:flex-start;color:var(--dia-texto-suave)}.rod li .dia-ic{width:16px;height:16px;margin-top:4px;flex:0 0 16px;color:var(--dia-primaria)}
.rod p{color:var(--dia-texto-suave);max-width:340px;margin-top:14px}
.rod-base{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;border-top:1px solid var(--dia-borda);margin-top:clamp(40px,6vw,70px);padding-top:22px;font-size:13.5px;color:var(--dia-texto-suave)}
.redes{display:flex;gap:10px;margin-top:20px}.redes a{width:40px;height:40px;border-radius:50%;display:grid;place-items:center;border:1px solid var(--dia-borda)}.redes .dia-ic{width:17px;height:17px}
.rod-gigante{font-family:var(--dia-fonte-titulos),serif;font-weight:800;font-size:clamp(56px,14vw,200px);line-height:.86;letter-spacing:-.05em;margin-top:clamp(40px,6vw,80px);opacity:.95;overflow-wrap:anywhere}
.rod-cta{display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap;padding-bottom:clamp(40px,6vw,64px);margin-bottom:clamp(40px,6vw,64px);border-bottom:1px solid var(--dia-borda)}
.rod-cta h3{font-size:clamp(28px,4vw,48px);max-width:640px}
.rod-min{display:flex;align-items:center;justify-content:space-between;gap:18px;flex-wrap:wrap}
.rod-min nav{display:flex;gap:18px;flex-wrap:wrap}
@media (max-width:820px){.rod-grelha{grid-template-columns:repeat(2,minmax(0,1fr))}.rod-grelha>div:first-child{grid-column:1/-1}}
.rod-grelha>div{min-width:0}.rod a,.rod li,.rod p{overflow-wrap:anywhere}
@media (max-width:420px){.rod-grelha{grid-template-columns:minmax(0,1fr)}}
/* ---- hero ---- */
.hero{position:relative;overflow:hidden}
.hero h1{font-size:clamp(42px,7.2vw,96px);margin:18px 0 20px}
.hero .lead{max-width:600px;margin-bottom:30px}
.hero-nota{display:flex;align-items:center;gap:12px;margin-top:30px;font-size:14px;color:var(--dia-texto-suave)}
.hero-nota .avs{display:flex}.hero-nota .avs b{width:36px;height:36px;border-radius:50%;border:2px solid var(--dia-fundo);margin-left:-10px;display:grid;place-items:center;font-size:12px;color:var(--dia-primaria-texto);background:var(--dia-primaria)}
.hero-nota .avs b:first-child{margin-left:0}.hero-nota .avs b:nth-child(2){background:var(--t-destaque)}.hero-nota .avs b:nth-child(3){background:color-mix(in srgb,var(--dia-primaria) 60%,var(--dia-texto))}
.h-dividido{padding:clamp(48px,7vw,96px) 0 clamp(56px,8vw,110px)}
.h-dividido .duas{grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr)}
.h-dividido .foto{aspect-ratio:4/4.6;border-radius:var(--t-raio-foto)}
.h-flutua{position:absolute;display:flex;align-items:center;gap:12px;padding:14px 18px;border-radius:calc(var(--dia-raio)*1.1);background:var(--dia-superficie);color:var(--dia-texto);border:1px solid var(--dia-borda);box-shadow:0 24px 50px -24px rgba(0,0,0,.45);font-size:14px;z-index:2}
.h-flutua b{display:block;font-family:var(--dia-fonte-titulos),serif;font-size:22px;line-height:1}
.h-flutua.f1{left:-24px;bottom:12%}.h-flutua.f2{right:-14px;top:9%}
.h-foto{min-height:min(88vh,860px);display:flex;align-items:flex-end;color:#fff;--dia-texto:#fff;--dia-texto-suave:rgba(255,255,255,.82);padding:clamp(120px,16vw,200px) 0 clamp(48px,7vw,90px)}
.h-foto .fundo{position:absolute;inset:0;z-index:0}.h-foto .fundo .foto{height:100%;border-radius:0}.h-foto .fundo img,.h-foto .fundo .arte{width:100%;height:100%;object-fit:cover}
.h-foto .fundo::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.15) 0%,rgba(0,0,0,.35) 40%,rgba(0,0,0,.78) 100%)}
.h-foto .w{position:relative;z-index:1}.h-foto h1{max-width:980px}.h-foto .etq{color:#fff}
.h-foto .btn-s{color:#fff}
.h-tipo{padding:clamp(70px,11vw,150px) 0 clamp(40px,6vw,70px)}
.h-tipo h1{font-size:clamp(52px,11vw,170px);line-height:.92;letter-spacing:-.045em;max-width:14ch}
.h-tipo .linha{display:flex;justify-content:space-between;align-items:flex-end;gap:30px;flex-wrap:wrap;margin-top:24px}
.h-tipo .lead{margin:0}
.h-centrado{text-align:center;padding:clamp(70px,10vw,140px) 0 0;background:radial-gradient(70% 60% at 50% 0%,color-mix(in srgb,var(--dia-primaria) 22%,transparent),transparent 70%)}
.h-centrado .lead{margin-inline:auto}.h-centrado .btns{justify-content:center}.h-centrado .etq{justify-content:center}
.h-centrado h1{max-width:16ch;margin-inline:auto}
.h-centrado .palco{margin-top:clamp(40px,6vw,70px);position:relative}
.h-centrado .palco .foto{aspect-ratio:16/7;border-radius:var(--t-raio-foto) var(--t-raio-foto) 0 0}
.h-centrado .chips{position:absolute;inset:auto 0 22px 0;display:flex;justify-content:center;gap:12px;flex-wrap:wrap;z-index:2}
.h-mosaico{padding:clamp(56px,8vw,110px) 0}
.h-mosaico .mos{display:grid;grid-template-columns:1fr 1fr;grid-template-rows:200px 200px 200px;gap:14px}
.h-mosaico .mos .foto:nth-child(1){grid-row:1/3}.h-mosaico .mos .foto:nth-child(4){grid-column:1/3}
.h-mosaico .mos .foto{border-radius:var(--dia-raio)}
.h-editorial{padding:clamp(40px,6vw,80px) 0 clamp(56px,8vw,100px);border-bottom:1px solid var(--dia-borda)}
.h-editorial .topo{display:flex;justify-content:space-between;font-size:12.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--dia-texto-suave);border-bottom:1px solid var(--dia-borda);padding-bottom:14px;margin-bottom:clamp(28px,5vw,60px)}
.h-editorial .ed{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,.7fr);gap:clamp(24px,5vw,70px);align-items:end}
.h-editorial h1{font-size:clamp(48px,9vw,140px);line-height:.9;margin:0}
.h-editorial .foto{aspect-ratio:3/4}
.h-cartao{padding:clamp(20px,3vw,32px) 0 clamp(56px,7vw,90px)}
.h-cartao .palco{position:relative;border-radius:var(--t-raio-foto);overflow:hidden;min-height:min(82vh,760px);display:flex;align-items:flex-end;padding:clamp(16px,3vw,36px)}
.h-cartao .palco>.foto{position:absolute;inset:0;border-radius:0}
.h-cartao .cx{position:relative;z-index:1;max-width:620px;background:var(--dia-fundo);border-radius:calc(var(--t-raio-foto)*.8);padding:clamp(24px,4vw,48px);box-shadow:0 30px 60px -30px rgba(0,0,0,.5)}
.h-cartao h1{font-size:clamp(38px,5.6vw,72px)}
.h-venda{padding:clamp(48px,7vw,96px) 0}
.h-venda .duas{grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);align-items:start}
.h-venda ul{list-style:none;padding:0;margin:0 0 28px;display:grid;gap:12px}
.h-venda li{display:flex;gap:12px;align-items:flex-start;font-weight:600}.h-venda li .dia-ic{width:22px;height:22px;flex:0 0 22px;color:var(--t-etq-cor);margin-top:2px}
.oferta{position:sticky;top:96px}
.oferta .foto{aspect-ratio:4/3;border-radius:calc(var(--dia-raio)*.8);margin-bottom:18px}
.oferta .preco{display:flex;align-items:baseline;gap:12px;margin:8px 0 18px}.oferta .preco b{font-family:var(--dia-fonte-titulos),serif;font-size:44px;line-height:1}.oferta .preco s{color:var(--dia-texto-suave);font-size:18px}
.oferta .btn{width:100%}
.oferta small{display:flex;align-items:center;justify-content:center;gap:8px;color:var(--dia-texto-suave);margin-top:12px;font-size:13px}.oferta small .dia-ic{width:15px;height:15px}
.h-perfil{padding:clamp(60px,9vw,130px) 0 clamp(40px,6vw,80px)}
.h-perfil .disp{display:inline-flex;align-items:center;gap:10px;padding:8px 16px;border-radius:999px;border:1px solid var(--dia-borda);font-size:14px;font-weight:600}
.h-perfil .disp i{width:9px;height:9px;border-radius:50%;background:#22c55e;box-shadow:0 0 0 4px rgba(34,197,94,.2)}
.h-perfil h1{font-size:clamp(46px,9vw,130px);line-height:.95;letter-spacing:-.045em;margin:26px 0}
.h-perfil .disc{display:flex;flex-wrap:wrap;gap:10px;margin-top:26px}
.h-perfil .disc span{padding:10px 18px;border-radius:999px;background:var(--dia-superficie);border:1px solid var(--dia-borda);font-weight:600;font-size:14.5px}
.h-perfil .faixa{display:grid;grid-template-columns:2fr 1fr 1fr;gap:14px;margin-top:clamp(40px,6vw,70px)}
.h-perfil .faixa .foto{aspect-ratio:auto;height:clamp(200px,28vw,380px)}
.h-loja{padding:clamp(24px,4vw,40px) 0 clamp(30px,4vw,50px)}
.h-loja .palco{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(0,1fr);gap:16px}
.h-loja .grande{position:relative;border-radius:var(--t-raio-foto);overflow:hidden;min-height:clamp(380px,46vw,560px);display:flex;align-items:flex-end;padding:clamp(24px,4vw,52px);color:#fff;--dia-texto-suave:rgba(255,255,255,.85)}
.h-loja .grande>.foto{position:absolute;inset:0;border-radius:0}.h-loja .grande>.foto::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(0,0,0,.66),rgba(0,0,0,.1))}
.h-loja .grande .cx{position:relative;z-index:1;max-width:520px}.h-loja .grande .etq{color:#fff}
.h-loja h1{font-size:clamp(36px,5.4vw,68px)}
.h-foto .fundo .arte .dia-ic,.h-loja .grande>.foto .arte .dia-ic,.h-galeria .palco>.foto .arte .dia-ic{display:none}
.h-foto em.dest,.h-loja .grande em.dest,.h-galeria em.dest{color:color-mix(in srgb,var(--t-dest-cor) 55%,#fff)}
.h-loja .lado{display:grid;gap:16px}
.h-loja .mini{position:relative;border-radius:var(--t-raio-foto);overflow:hidden;min-height:180px;padding:24px;display:flex;flex-direction:column;justify-content:flex-end;background:var(--t-fundo2);text-decoration:none}
.h-loja .mini.c1{background:color-mix(in srgb,var(--dia-primaria) 16%,var(--dia-superficie))}.h-loja .mini.c2{background:color-mix(in srgb,var(--t-destaque) 20%,var(--dia-superficie))}
.h-loja .mini b{font-family:var(--dia-fonte-titulos),serif;font-size:24px;line-height:1.1;max-width:60%;position:relative;z-index:1}.h-loja .mini span{font-weight:700;font-size:14px;margin-top:10px;display:inline-flex;align-items:center;gap:6px;position:relative;z-index:1}
.h-loja .mini .foto{position:absolute;right:-6%;bottom:-8%;width:52%;height:90%;background:transparent}.h-loja .mini .foto img{object-fit:cover;border-radius:var(--dia-raio)}
.h-galeria{padding:0}.h-galeria .palco{position:relative;height:min(92vh,900px);overflow:hidden;color:#fff}
.h-galeria .palco .foto{position:absolute;inset:0;border-radius:0}
.h-galeria .palco::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.05),rgba(0,0,0,.65))}
.h-galeria .cx{position:absolute;left:0;right:0;bottom:clamp(28px,6vw,70px);z-index:2}
.h-galeria h1{font-size:clamp(44px,8vw,120px);max-width:12ch;line-height:.95}.h-galeria .lead{color:rgba(255,255,255,.86)}
.h-galeria .etq{color:#fff}.h-galeria .btn-s{color:#fff}
@media (max-width:900px){
  .duas,.h-dividido .duas,.h-venda .duas,.h-editorial .ed,.h-loja .palco{grid-template-columns:1fr}
  .h-dividido .foto{aspect-ratio:4/3.4}.h-flutua.f1{left:8px}.h-flutua.f2{right:8px}
  .oferta{position:static}
  .h-mosaico .mos{grid-template-rows:150px 150px 150px}
  .h-perfil .faixa{grid-template-columns:1fr 1fr}.h-perfil .faixa .foto:first-child{grid-column:1/-1}
  .h-centrado .palco .foto{aspect-ratio:4/3}
}
/* ---- faixas ---- */
.marquee{overflow:hidden;padding:22px 0;border-block:1px solid var(--dia-borda);background:var(--dia-fundo)}
.marquee.cor{background:var(--dia-primaria);color:var(--dia-primaria-texto);border:0}
.marquee .trilho{display:flex;gap:44px;width:max-content;animation:tpl-mq 38s linear infinite}
.marquee span{display:inline-flex;align-items:center;gap:44px;font-family:var(--dia-fonte-titulos),serif;font-size:clamp(20px,2.6vw,30px);font-weight:700;white-space:nowrap}
.marquee span::after{content:"✦";font-size:.6em;opacity:.6}
@keyframes tpl-mq{to{transform:translateX(-50%)}}
@media (prefers-reduced-motion:reduce){.marquee .trilho{animation:none}}
.logos{display:flex;flex-wrap:wrap;justify-content:center;gap:clamp(18px,4vw,56px);opacity:.75}
.logos span{display:inline-flex;align-items:center;gap:10px;font-family:var(--dia-fonte-titulos),serif;font-weight:800;font-size:20px;letter-spacing:-.02em}
.logos i{width:30px;height:30px;border-radius:8px;border:2px solid currentColor;display:grid;place-items:center;font-style:normal;font-size:13px}
/* ---- números ---- */
.nums{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:clamp(16px,3vw,40px)}
.num{min-width:0}.num b{display:block;overflow-wrap:anywhere;font-family:var(--dia-fonte-titulos),serif;font-size:clamp(32px,6vw,78px);line-height:1;letter-spacing:-.04em}
.num span{display:block;margin-top:10px;color:var(--dia-texto-suave);font-size:15px}
.num-cartoes .num{background:var(--dia-superficie);border:var(--t-borda) solid var(--dia-borda);border-radius:var(--dia-raio);padding:28px}
.num-faixa .num{border-left:2px solid color-mix(in srgb,currentColor 18%,transparent);padding-left:clamp(14px,2vw,24px)}
@media (max-width:760px){.nums{grid-template-columns:1fr 1fr}}
/* ---- serviços ---- */
.svc h3{font-size:clamp(20px,2vw,24px);margin:20px 0 10px}
.svc p{color:var(--dia-texto-suave)}
.svc ul{list-style:none;padding:0;margin:18px 0 0;display:grid;gap:8px;font-size:15px}
.svc li{display:flex;gap:9px;align-items:flex-start}.svc li .dia-ic{width:17px;height:17px;flex:0 0 17px;margin-top:4px;color:var(--t-etq-cor)}
.svc .rodape-svc{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:22px;padding-top:18px;border-top:1px solid var(--dia-borda)}
.svc .preco{font-weight:800;font-size:15px}
.svc-num{font-family:var(--dia-fonte-titulos),serif;font-size:14px;font-weight:700;color:var(--dia-texto-suave)}
.alternado{display:grid;gap:clamp(48px,8vw,110px)}
.alternado .duas:nth-child(even) .foto{order:2}
.alternado .foto{aspect-ratio:5/4}
.alternado h3{font-size:clamp(28px,3.6vw,44px);margin:14px 0 16px}
.alternado ul{list-style:none;padding:0;margin:22px 0 26px;display:grid;gap:10px}
.alternado li{display:flex;gap:10px}.alternado li .dia-ic{width:20px;height:20px;flex:0 0 20px;color:var(--t-etq-cor);margin-top:3px}
.bento{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:16px}
.bento>*{grid-column:span 2}.bento>*:nth-child(1){grid-column:span 4;grid-row:span 2}.bento>*:nth-child(4):last-child{grid-column:span 6}.bento>*:nth-child(5):last-child{grid-column:span 4}
.bento .cartao{display:flex;flex-direction:column}
.bento .cartao:nth-child(1){background:var(--dia-primaria);color:var(--dia-primaria-texto);--dia-texto-suave:color-mix(in srgb,var(--dia-primaria-texto) 80%,transparent);border-color:transparent;justify-content:flex-end;min-height:360px;position:relative;overflow:hidden}
.bento .cartao:nth-child(1) .icx{background:color-mix(in srgb,var(--dia-primaria-texto) 16%,transparent);color:inherit}
.bento .cartao:nth-child(1) h3{font-size:clamp(28px,3.4vw,40px)}
.bento .cartao:nth-child(1) .foto{position:absolute;inset:0;border-radius:0;opacity:.28}
.bento .cartao:nth-child(1)>*:not(.foto){position:relative}
@media (max-width:900px){.bento{grid-template-columns:1fr 1fr}.bento>*,.bento>*:nth-child(n){grid-column:span 1;grid-row:auto}.bento>*:nth-child(1){grid-column:1/-1}}
@media (max-width:560px){.bento{grid-template-columns:1fr}}
.lista-svc{border-top:1px solid var(--dia-borda)}
.lista-svc a,.lista-svc div.it{display:grid;grid-template-columns:70px minmax(0,1.1fr) minmax(0,1.4fr) auto;gap:24px;align-items:center;padding:28px 0;border-bottom:1px solid var(--dia-borda);text-decoration:none;transition:padding .3s,background .3s}
.lista-svc a:hover{padding-inline:16px;background:var(--dia-superficie)}
.lista-svc h3{font-size:clamp(22px,2.6vw,32px)}
.lista-svc .dia-ic{width:22px;height:22px}
@media (max-width:760px){.lista-svc a,.lista-svc div.it{grid-template-columns:44px 1fr;gap:12px}.lista-svc p,.lista-svc .preco{grid-column:2}}
.abas-nav{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:26px}
.abas-nav button{font:inherit;font-weight:700;padding:11px 20px;border-radius:999px;border:1px solid var(--dia-borda);background:transparent;color:inherit;cursor:pointer}
.abas-nav button[aria-selected="true"]{background:var(--dia-primaria);color:var(--dia-primaria-texto);border-color:transparent}
.aba[hidden]{display:none}
html:not(.js) .aba[hidden]{display:block;margin-bottom:24px}
/* ---- sobre ---- */
.sobre .foto{aspect-ratio:4/5}
.sobre .foto-par{position:relative}
.sobre .foto-par .mini{position:absolute;width:46%;aspect-ratio:1;right:-6%;bottom:-8%;border:6px solid var(--dia-fundo);border-radius:var(--dia-raio)}
@media (max-width:900px){.sobre .foto-par .mini{right:0;width:42%}}
.sobre h2{font-size:clamp(30px,4.4vw,52px);margin:16px 0 20px}
.sobre p+p{margin-top:14px}
.sobre .vals{display:grid;gap:18px;margin-top:30px}
.sobre .val{display:flex;gap:16px;align-items:flex-start}.sobre .val h4{font-size:18px;margin-bottom:4px}
.citacao{font-family:var(--dia-fonte-titulos),serif;font-size:clamp(26px,3.8vw,46px);line-height:1.18;letter-spacing:-.02em;max-width:1000px}
.citacao .dia-ic{width:46px;height:46px;color:var(--t-etq-cor);margin-bottom:18px}
.citacao cite{display:block;margin-top:22px;font-family:var(--dia-fonte-texto);font-size:15px;font-style:normal;color:var(--dia-texto-suave)}
.ed-cols{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(28px,6vw,90px)}
.ed-cols h2{font-size:clamp(36px,5.4vw,70px)}
.ed-cols .txt{columns:2 260px;column-gap:40px}.ed-cols .txt p{margin-bottom:14px;break-inside:avoid}
@media (max-width:900px){.ed-cols{grid-template-columns:1fr}}
.marcos{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:20px;margin-top:clamp(40px,6vw,70px)}
.marco{border-top:2px solid var(--dia-primaria);padding-top:16px}.marco b{font-family:var(--dia-fonte-titulos),serif;font-size:28px;display:block;margin-bottom:6px}
/* ---- processo ---- */
.passos{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:clamp(18px,3vw,34px);counter-reset:p}
.passo{position:relative;padding-top:66px}
.passo::before{counter-increment:p;content:counter(p,decimal-leading-zero);position:absolute;top:0;left:0;font-family:var(--dia-fonte-titulos),serif;font-size:44px;font-weight:800;line-height:1;color:var(--t-etq-cor);opacity:.9}
.passo::after{content:"";position:absolute;top:22px;left:76px;right:-20px;height:1px;background:repeating-linear-gradient(90deg,var(--dia-borda) 0 6px,transparent 6px 12px)}
.passo:last-child::after{display:none}
.passo h3{font-size:21px;margin-bottom:10px}.passo p{color:var(--dia-texto-suave)}
.tl{position:relative;display:grid;gap:clamp(22px,4vw,40px);max-width:860px}
.tl::before{content:"";position:absolute;left:23px;top:8px;bottom:8px;width:2px;background:linear-gradient(var(--dia-primaria),color-mix(in srgb,var(--dia-primaria) 10%,transparent))}
.tl-it{display:grid;grid-template-columns:48px 1fr;gap:22px}
.tl-it>b{width:48px;height:48px;border-radius:50%;display:grid;place-items:center;background:var(--dia-primaria);color:var(--dia-primaria-texto);font-weight:800;position:relative}
.tl-it h3{font-size:22px;margin:8px 0}.tl-it p{color:var(--dia-texto-suave)}
.circs{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,200px),1fr));gap:24px;text-align:center}
.circs .c{display:flex;flex-direction:column;align-items:center}
.circs .c i{width:96px;height:96px;border-radius:50%;display:grid;place-items:center;border:2px dashed color-mix(in srgb,var(--dia-primaria) 55%,transparent);margin-bottom:18px;font-style:normal;font-family:var(--dia-fonte-titulos),serif;font-size:28px;font-weight:800;color:var(--t-etq-cor)}
.circs h3{font-size:20px;margin-bottom:8px}.circs p{color:var(--dia-texto-suave);max-width:260px}
/* ---- benefícios ---- */
.bnf{display:flex;gap:18px;align-items:flex-start}.bnf h3{font-size:19px;margin-bottom:6px}.bnf p{color:var(--dia-texto-suave);font-size:15.5px}
.sticky-duas{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,.8fr);gap:clamp(28px,5vw,70px);align-items:start}
.sticky-duas .cartao.fixo{position:sticky;top:100px}
.vistos{list-style:none;padding:0;margin:0;display:grid;gap:14px}
.vistos li{display:flex;gap:14px;align-items:flex-start;padding:18px 20px;border-radius:var(--dia-raio);background:var(--dia-superficie);border:var(--t-borda) solid var(--dia-borda)}
.vistos li .dia-ic{width:24px;height:24px;flex:0 0 24px;color:var(--t-etq-cor);margin-top:2px}
.vistos b{display:block;font-size:17px;margin-bottom:2px}
@media (max-width:900px){.sticky-duas{grid-template-columns:1fr}.sticky-duas .cartao.fixo{position:static}}
/* ---- testemunhos ---- */
.dep{display:flex;flex-direction:column;gap:20px}
.dep blockquote{margin:0;font-size:16.5px;line-height:1.65}
.dep .quem{display:flex;align-items:center;gap:12px;margin-top:auto}
.av{width:46px;height:46px;border-radius:50%;flex:0 0 46px;display:grid;place-items:center;font-weight:800;background:color-mix(in srgb,var(--dia-primaria) 18%,var(--dia-superficie));color:var(--t-etq-cor)}
.dep .quem b{display:block;font-size:15px}.dep .quem small{color:var(--dia-texto-suave)}
.dep-grande{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(0,1fr);gap:clamp(24px,4vw,56px);align-items:center}
.dep-grande .citacao{font-size:clamp(24px,3.2vw,40px)}
.dep-lado{display:grid;gap:16px}
@media (max-width:900px){.dep-grande{grid-template-columns:1fr}}
.carrossel{display:grid;grid-auto-flow:column;grid-auto-columns:min(86%,420px);gap:20px;overflow-x:auto;scroll-snap-type:x mandatory;padding-bottom:14px;scrollbar-width:thin}
.carrossel>*{scroll-snap-align:start}
.setas{display:flex;gap:10px}.setas button{width:48px;height:48px;border-radius:50%;border:1px solid var(--dia-borda);background:var(--dia-superficie);color:inherit;display:grid;place-items:center;cursor:pointer}.setas .dia-ic{width:20px;height:20px}
/* ---- preços ---- */
.precos{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,290px),1fr));gap:20px;align-items:stretch}
.plano{display:flex;flex-direction:column;position:relative}
.plano.dest{background:var(--t-escuro);color:var(--t-escuro-texto);--dia-texto-suave:var(--t-escuro-suave);--dia-borda:rgba(255,255,255,.14);border-color:transparent;transform:translateY(-10px)}
.plano .selo{position:absolute;top:18px;right:18px;padding:6px 12px;border-radius:999px;background:var(--dia-primaria);color:var(--dia-primaria-texto);font-size:12px;font-weight:800}
.plano h3{font-size:22px}.plano .desc{color:var(--dia-texto-suave);margin:8px 0 20px;font-size:15px}
.plano .valor{font-family:var(--dia-fonte-titulos),serif;font-size:clamp(36px,4vw,48px);line-height:1;letter-spacing:-.03em}.plano .valor small{font-family:var(--dia-fonte-texto);font-size:15px;color:var(--dia-texto-suave);letter-spacing:0}
.plano ul{list-style:none;padding:0;margin:24px 0 28px;display:grid;gap:11px;font-size:15.5px}
.plano li{display:flex;gap:10px}.plano li .dia-ic{width:18px;height:18px;flex:0 0 18px;margin-top:3px;color:var(--dia-primaria)}
.plano .btn{margin-top:auto;width:100%}
/* ---- comparação ---- */
.comp{border:var(--t-borda) solid var(--dia-borda);border-radius:var(--dia-raio);overflow:hidden;background:var(--dia-superficie)}
.comp table{width:100%;border-collapse:collapse}
.comp th,.comp td{padding:18px 22px;text-align:left;border-bottom:1px solid var(--dia-borda)}
.comp th{font-size:14px;text-transform:uppercase;letter-spacing:.08em}
.comp th:nth-child(2),.comp td:nth-child(2){background:color-mix(in srgb,var(--dia-primaria) 9%,transparent)}
.comp td:not(:first-child),.comp th:not(:first-child){text-align:center;width:22%}
.comp .dia-ic{width:22px;height:22px;margin:auto}.comp .sim{color:#16a34a}.comp .nao{color:#dc2626;opacity:.75}
.comp tr:last-child td{border-bottom:0}
/* ---- FAQ ---- */
.faq{display:grid;gap:12px}
.faq details{background:var(--dia-superficie);border:var(--t-borda) solid var(--dia-borda);border-radius:var(--dia-raio);padding:0 24px;transition:border-color .2s}
.faq details[open]{border-color:color-mix(in srgb,var(--dia-primaria) 50%,var(--dia-borda))}
.faq summary{list-style:none;cursor:pointer;display:flex;justify-content:space-between;align-items:center;gap:16px;padding:22px 0;font-weight:700;font-size:17px}
.faq summary::-webkit-details-marker{display:none}
.faq summary .dia-ic{width:20px;height:20px;flex:0 0 20px;transition:transform .3s;color:var(--t-etq-cor)}
.faq details[open] summary .dia-ic{transform:rotate(45deg)}
.faq details p{padding:0 0 22px;color:var(--dia-texto-suave)}
.faq-duas{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:clamp(28px,5vw,70px);align-items:start}
.faq-duas .s-cab{position:sticky;top:110px}
@media (max-width:900px){.faq-duas{grid-template-columns:1fr}.faq-duas .s-cab{position:static}}
/* ---- CTA ---- */
.cta-faixa{display:flex;align-items:center;justify-content:space-between;gap:30px;flex-wrap:wrap}
.cta-faixa h2{font-size:clamp(30px,4.6vw,58px);max-width:760px}
.cta-faixa p{margin-top:12px;max-width:620px;color:var(--dia-texto-suave);font-size:18px}
.cta-foto{position:relative;border-radius:var(--t-raio-foto);overflow:hidden;color:#fff;padding:clamp(56px,9vw,120px) clamp(24px,6vw,80px);text-align:center;--dia-texto-suave:rgba(255,255,255,.85)}
.cta-foto>.foto{position:absolute;inset:0;border-radius:0}.cta-foto>.foto::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.45),rgba(0,0,0,.7))}
.cta-foto>*:not(.foto){position:relative}
.cta-foto h2{font-size:clamp(32px,5vw,64px);max-width:840px;margin:0 auto 16px}
.cta-foto p{max-width:600px;margin:0 auto 30px;font-size:18px}.cta-foto .btns{justify-content:center}.cta-foto .btn-s{color:#fff}
.cta-cartao{border-radius:var(--t-raio-foto);background:var(--dia-primaria);color:var(--dia-primaria-texto);padding:clamp(36px,6vw,80px);display:grid;grid-template-columns:minmax(0,1.3fr) auto;gap:30px;align-items:center;position:relative;overflow:hidden;--dia-texto-suave:color-mix(in srgb,var(--dia-primaria-texto) 80%,transparent)}
.cta-cartao::before{content:"";position:absolute;width:420px;height:420px;border-radius:50%;right:-120px;top:-160px;background:color-mix(in srgb,var(--dia-primaria-texto) 10%,transparent)}
.cta-cartao>*{position:relative}.cta-cartao h2{font-size:clamp(28px,4vw,50px)}.cta-cartao p{margin-top:12px;color:var(--dia-texto-suave)}
.cta-cartao .btn-p{background:var(--dia-primaria-texto);color:var(--dia-primaria)}.cta-cartao .btn-s{color:inherit}
@media (max-width:760px){.cta-cartao{grid-template-columns:1fr}}
/* ---- galeria ---- */
.masonry{columns:3 260px;column-gap:16px}
.masonry figure{margin:0 0 16px;break-inside:avoid;position:relative;border-radius:var(--dia-raio);overflow:hidden}
.masonry figure .foto{border-radius:0}.masonry figure:nth-child(3n+1) .foto{aspect-ratio:4/5}.masonry figure:nth-child(3n+2) .foto{aspect-ratio:1}.masonry figure:nth-child(3n) .foto{aspect-ratio:4/3}
.masonry figcaption{position:absolute;left:12px;right:12px;bottom:12px;padding:10px 14px;border-radius:12px;background:rgba(0,0,0,.55);color:#fff;font-size:14px;font-weight:600;opacity:0;transform:translateY(8px);transition:.3s}
.masonry figure:hover figcaption{opacity:1;transform:none}
@media (hover:none){.masonry figcaption{opacity:1;transform:none}}
.grelha-fotos{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:12px}.grelha-fotos .foto{aspect-ratio:1}
/* ---- equipa ---- */
.pessoa{text-align:left}.pessoa .foto{aspect-ratio:4/5;margin-bottom:18px}
.pessoa .mono{aspect-ratio:4/5;border-radius:var(--t-raio-foto);display:grid;place-items:center;margin-bottom:18px;font-family:var(--dia-fonte-titulos),serif;font-size:64px;font-weight:800;color:var(--t-etq-cor);background:radial-gradient(80% 70% at 30% 20%,color-mix(in srgb,var(--dia-primaria) 30%,transparent),transparent),var(--dia-superficie);border:var(--t-borda) solid var(--dia-borda)}
.pessoa h3{font-size:21px}.pessoa small{display:block;color:var(--t-etq-cor);font-weight:700;margin:4px 0 10px}.pessoa p{color:var(--dia-texto-suave);font-size:15px}
/* ---- garantia ---- */
.garantia{display:grid;grid-template-columns:auto minmax(0,1fr);gap:clamp(24px,4vw,48px);align-items:center;max-width:980px;margin:auto}
.selo{width:clamp(130px,16vw,180px);aspect-ratio:1;border-radius:50%;display:grid;place-items:center;text-align:center;background:var(--dia-primaria);color:var(--dia-primaria-texto);box-shadow:0 0 0 10px color-mix(in srgb,var(--dia-primaria) 18%,transparent),0 0 0 22px color-mix(in srgb,var(--dia-primaria) 8%,transparent)}
.selo .dia-ic{width:56px;height:56px;margin:0 auto 4px;stroke-width:1.6}.selo b{font-size:13px;letter-spacing:.12em;text-transform:uppercase}
.garantia h2{font-size:clamp(28px,4vw,46px);margin-bottom:14px}
@media (max-width:640px){.garantia{grid-template-columns:1fr;text-align:center}.selo{margin:auto}}
/* ---- contacto ---- */
.ctt{display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr);gap:clamp(24px,4vw,56px);align-items:start}
.ctt-lista{display:grid;gap:14px;min-width:0}.ctt-lista a,.ctt-lista div{min-width:0;overflow-wrap:anywhere}
.ctt-lista a,.ctt-lista div{display:flex;gap:16px;align-items:center;text-decoration:none;padding:18px;border-radius:var(--dia-raio);background:var(--dia-superficie);border:var(--t-borda) solid var(--dia-borda)}
.ctt-lista small{display:block;color:var(--dia-texto-suave);font-size:13px}.ctt-lista b{font-size:16px}
.mapa{position:relative;border-radius:var(--t-raio-foto);overflow:hidden;min-height:300px;background:linear-gradient(0deg,color-mix(in srgb,var(--dia-primaria) 8%,var(--dia-superficie)),var(--dia-superficie));border:var(--t-borda) solid var(--dia-borda)}
.mapa svg.ruas{position:absolute;inset:0;width:100%;height:100%;color:color-mix(in srgb,var(--dia-texto) 14%,transparent)}
.mapa .pin{position:absolute;left:50%;top:46%;transform:translate(-50%,-100%);display:flex;flex-direction:column;align-items:center;gap:8px}
.mapa .pin i{width:54px;height:54px;border-radius:50% 50% 50% 4px;transform:rotate(-45deg);background:var(--dia-primaria);display:grid;place-items:center;box-shadow:0 14px 30px -10px color-mix(in srgb,var(--dia-primaria) 80%,transparent)}
.mapa .pin i .dia-ic{transform:rotate(45deg);color:var(--dia-primaria-texto);width:24px;height:24px}
.mapa .pin span{padding:8px 14px;border-radius:999px;background:var(--dia-superficie);font-weight:700;font-size:14px;box-shadow:0 10px 24px -14px rgba(0,0,0,.4);white-space:nowrap}
.horario{display:grid;gap:10px}.horario div{display:flex;justify-content:space-between;gap:16px;padding:12px 0;border-bottom:1px dashed var(--dia-borda)}
.estado-aberto{display:inline-flex;align-items:center;gap:8px;font-weight:700;font-size:14px;margin-bottom:12px}.estado-aberto .dia-ic{width:18px;height:18px;color:var(--t-etq-cor)}
@media (max-width:900px){.ctt{grid-template-columns:1fr}}
/* ---- menu (restaurante) ---- */
.menu-cats{display:grid;gap:clamp(36px,5vw,60px)}
.menu-cat h3{font-size:clamp(24px,3vw,34px);margin-bottom:18px;display:flex;align-items:center;gap:14px}
.menu-cat h3::after{content:"";flex:1;height:1px;background:var(--dia-borda)}
.menu-it{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:6px 20px;padding:16px 0;border-bottom:1px dashed var(--dia-borda)}
.menu-it b{font-size:17.5px}.menu-it span{font-weight:800;color:var(--t-etq-cor);white-space:nowrap}.menu-it p{grid-column:1/-1;color:var(--dia-texto-suave);font-size:15px}
.menu-duas{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,420px),1fr));gap:clamp(24px,4vw,56px)}
/* ---- para quem / venda ---- */
.perfil-c h3{font-size:20px;margin:18px 0 8px}.perfil-c p{color:var(--dia-texto-suave)}
.inclui{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:14px}
.bonus{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:16px}
.bonus .cartao{border-style:dashed}
.bonus small{display:inline-block;font-weight:800;letter-spacing:.1em;text-transform:uppercase;color:var(--t-etq-cor);font-size:12px;margin-bottom:8px}
/* ---- topo das páginas ---- */
.topo-pg{padding:clamp(56px,8vw,110px) 0 clamp(40px,6vw,70px);position:relative;overflow:hidden}
.topo-pg .mig{display:flex;gap:8px;font-size:13.5px;color:var(--dia-texto-suave);margin-bottom:18px}.topo-pg .mig a{text-decoration:none}
.topo-pg h1{font-size:clamp(40px,7vw,92px);max-width:16ch}
.topo-pg .lead{margin-top:18px;max-width:640px}
.topo-pg.v-foto{color:#fff;--dia-texto:#fff;--dia-texto-suave:rgba(255,255,255,.84);min-height:420px;display:flex;align-items:flex-end}
.topo-pg.v-foto>.foto{position:absolute;inset:0;border-radius:0}.topo-pg.v-foto>.foto::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.2),rgba(0,0,0,.72))}
.topo-pg.v-foto .w{position:relative}
.topo-pg.v-centrado{text-align:center;background:radial-gradient(60% 80% at 50% 0%,color-mix(in srgb,var(--dia-primaria) 18%,transparent),transparent 70%)}
.topo-pg.v-centrado h1,.topo-pg.v-centrado .lead{margin-inline:auto}.topo-pg.v-centrado .mig{justify-content:center}
.topo-pg.v-simples{border-bottom:1px solid var(--dia-borda)}
/* ---- módulos ---- */
.s-modulo .s-cab-linha{margin-bottom:24px}
.s-quiz{padding-bottom:0}
.wa-faixa{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:24px;align-items:center;padding:clamp(24px,4vw,40px);border-radius:var(--t-raio-foto);background:var(--dia-superficie);border:var(--t-borda) solid var(--dia-borda)}
.wa-faixa .icx{background:#25D366;color:#fff;width:64px;height:64px}.wa-faixa h3{font-size:clamp(22px,2.8vw,30px)}.wa-faixa p{color:var(--dia-texto-suave);margin-top:6px}
@media (max-width:760px){.wa-faixa{grid-template-columns:1fr}}
`;

// ---- ajudas ----
function tEsc(v) { return escaparHtml(String(v == null ? '' : v)); }
function tLista(v, n) { return (Array.isArray(v) ? v : []).filter(Boolean).slice(0, n || 50); }
function tIniciais(nome) { return String(nome || '?').trim().split(/\s+/).slice(0, 2).map(p => p[0] || '').join('').toUpperCase() || '?'; }
function tTitulo(titulo, destaque) {
  const t = String(titulo || ''); const d = String(destaque || '').trim();
  if (d && d.length < t.length && t.toLowerCase().includes(d.toLowerCase())) {
    const i = t.toLowerCase().indexOf(d.toLowerCase());
    return tEsc(t.slice(0, i)) + '<em class="dest">' + tEsc(t.slice(i, i + d.length)) + '</em>' + tEsc(t.slice(i + d.length));
  }
  return tEsc(t);
}
function tIc(nome, reserva) { return svgIcone(iconeValido(nome, reserva)); }
function tEtq(txt) { return txt ? `<span class="etq">${tEsc(txt)}</span>` : ''; }
function tCab(c, etq, titulo, texto, extra) {
  return `<div class="s-cab${extra && extra.centro ? ' centro' : ''} rv">${tEtq(etq)}<h2>${tTitulo(titulo, extra && extra.destaque)}</h2>${texto ? `<p>${tEsc(texto)}</p>` : ''}</div>`;
}
// Foto pelo "uso" (capa, sobre, galeria-1...); sem foto, uma composição de arte.
function tFoto(c, uso, alt, classe, icone) {
  const url = c.fotoDe(uso);
  const cl = 'foto' + (classe ? ' ' + classe : '');
  if (url) return `<div class="${cl}"><img src="${tEsc(url)}" alt="${tEsc(alt || '')}" loading="${uso === 'capa' ? 'eager' : 'lazy'}"></div>`;
  return `<div class="${cl}"><div class="arte">${tIc(icone || c.icone)}</div></div>`;
}
function tBtnP(txt, href, icone) { return txt ? `<a class="btn btn-p" href="${tEsc(href || 'contacto.html')}">${tEsc(txt)}${tIc(icone || 'arrow-right')}</a>` : ''; }
function tBtnS(txt, href, icone) { return txt ? `<a class="btn btn-s" href="${tEsc(href || '#')}">${icone ? tIc(icone) : ''}${tEsc(txt)}</a>` : ''; }
function tWa(c) {
  const n = String((c.d.contacto && (c.d.contacto.whatsapp || c.d.contacto.telefone)) || '').replace(/[^\d]/g, '');
  return n ? 'https://wa.me/' + (n.length === 9 ? '258' + n : n) : 'contacto.html';
}
function tPagina(c, slug, reserva) {
  const p = (c.plano || []).find(x => x.slug === slug);
  return p ? p.ficheiro : (reserva || (slug === 'inicio' ? 'index.html' : 'contacto.html'));
}

// ---- secções ----
const TPL_SECCOES = {
  // HERO
  hero(c, v) {
    const h = c.d.hero || {}, d = c.d;
    const etq = tEtq(h.etiqueta);
    const titulo = `<h1>${tTitulo(h.titulo || d.marca.nome, h.destaque)}</h1>`;
    const lead = h.subtitulo ? `<p class="lead">${tEsc(h.subtitulo)}</p>` : '';
    const alvo1 = c.ctaPrincipal, alvo2 = c.ctaSecundario;
    const btns = `<div class="btns">${tBtnP(h.botao, alvo1)}${tBtnS(h.botao2, alvo2)}</div>`;
    const nota = h.nota ? `<div class="hero-nota"><span class="avs"><b>${tIc('star')}</b><b>${tIc('heart')}</b><b>${tIc('thumbs-up')}</b></span><span>${tEsc(h.nota)}</span></div>` : '';
    const n0 = tLista(d.numeros)[0], t0 = tLista(d.testemunhos)[0];
    if (v === 'foto-ecra') return `<section class="hero h-foto"><div class="fundo">${tFoto(c, 'capa', d.marca.nome)}</div><div class="w rv">${etq}${titulo}${lead}${btns}</div></section>`;
    if (v === 'tipografico') return `<section class="hero h-tipo"><div class="w">${etq}<h1 class="rv">${tTitulo(h.titulo || d.marca.nome, h.destaque)}</h1><div class="linha rv">${lead}${btns}</div></div></section>${TPL_SECCOES.marquee(c, 'cor')}`;
    if (v === 'centrado') return `<section class="hero h-centrado"><div class="w rv">${etq}${titulo}${lead}${btns}</div><div class="w palco rv">${tFoto(c, 'capa', d.marca.nome)}<div class="chips">${tLista(d.beneficios, 3).map(b => `<span class="chip">${tIc(b.icone, 'check')}${tEsc(b.titulo)}</span>`).join('')}</div></div></section>`;
    if (v === 'mosaico') return `<section class="hero h-mosaico"><div class="w duas"><div class="rv">${etq}${titulo}${lead}${btns}${nota}</div><div class="mos rv">${tFoto(c, 'capa', '')}${tFoto(c, 'galeria-1', '')}${tFoto(c, 'galeria-2', '')}${tFoto(c, 'sobre', '')}</div></div></section>`;
    if (v === 'editorial') return `<section class="hero h-editorial"><div class="w"><div class="topo"><span>${tEsc(d.marca.nome)}</span><span>${tEsc(d.marca.slogan || '')}</span></div><div class="ed"><div class="rv">${etq}<h1>${tTitulo(h.titulo || d.marca.nome, h.destaque)}</h1></div><div class="rv">${tFoto(c, 'capa', d.marca.nome)}${lead ? `<div style="margin-top:22px">${lead}</div>` : ''}${btns}</div></div></div></section>`;
    if (v === 'cartao') return `<section class="hero h-cartao"><div class="w"><div class="palco">${tFoto(c, 'capa', d.marca.nome)}<div class="cx rv">${etq}<h1>${tTitulo(h.titulo || d.marca.nome, h.destaque)}</h1>${lead}${btns}</div></div></div></section>`;
    if (v === 'venda') {
      const vd = d.venda || {};
      return `<section class="hero h-venda"><div class="w duas"><div class="rv">${etq}${titulo}${lead}<ul>${tLista(vd.inclui, 5).map(x => `<li>${tIc('circle-check')}${tEsc(x)}</li>`).join('')}</ul>${nota}</div><div class="cartao oferta rv">${tFoto(c, 'capa', vd.produto || '')}<span class="etq">${tEsc(c.txt.oferta)}</span><h3 style="font-size:24px;margin-top:10px">${tEsc(vd.produto || d.marca.nome)}</h3><div class="preco"><b>${tEsc(vd.preco || '')}</b>${vd.preco_antigo ? `<s>${tEsc(vd.preco_antigo)}</s>` : ''}</div><a class="btn btn-p" href="#oferta">${tEsc(h.botao || c.txt.oferta)}${tIc('arrow-down')}</a><small>${tIc('shield-check')}${tEsc((d.garantia && d.garantia.titulo) || '')}</small></div></div></section>`;
    }
    if (v === 'perfil') {
      const pf = d.portfolio || {};
      return `<section class="hero h-perfil"><div class="w"><span class="disp rv"><i></i>${tEsc(pf.disponivel || d.marca.slogan || '')}</span><h1 class="rv">${tTitulo(h.titulo || d.marca.nome, h.destaque)}</h1><div class="duas rv" style="align-items:end">${lead || '<span></span>'}<div class="btns" style="justify-content:flex-end">${tBtnP(h.botao, alvo1)}${tBtnS(h.botao2, alvo2)}</div></div><div class="disc rv">${tLista(pf.disciplinas, 6).map(x => `<span>${tEsc(x)}</span>`).join('')}</div><div class="faixa rv">${tFoto(c, 'capa', '')}${tFoto(c, 'galeria-1', '')}${tFoto(c, 'galeria-2', '')}</div></div></section>`;
    }
    if (v === 'loja') {
      const lj = d.loja || {}, cats = tLista(lj.categorias_destaque, 2);
      return `<section class="hero h-loja"><div class="w palco"><div class="grande">${tFoto(c, 'capa', d.marca.nome)}<div class="cx rv">${etq}${titulo}${lead}${btns}</div></div><div class="lado">${cats.map((x, i) => `<a class="mini c${i + 1} rv" href="${tPagina(c, 'loja')}"><b>${tEsc(x)}</b><span>${tEsc(c.txt.verTodos)}${tIc('arrow-right')}</span>${tFoto(c, 'galeria-' + (i + 1), x)}</a>`).join('')}</div></div></section>`;
    }
    if (v === 'galeria') return `<section class="hero h-galeria"><div class="palco">${tFoto(c, 'capa', d.marca.nome)}<div class="cx"><div class="w rv">${etq}${titulo}${lead}${btns}</div></div></div></section>`;
    // dividido (por omissão)
    return `<section class="hero h-dividido"><div class="w duas"><div class="rv">${etq}${titulo}${lead}${btns}${nota}</div><div class="rv" style="position:relative">${tFoto(c, 'capa', d.marca.nome)}${n0 ? `<div class="h-flutua f1"><span class="icx">${tIc('trending-up')}</span><div><b>${tEsc(n0.valor)}${tEsc(n0.sufixo || '')}</b>${tEsc(n0.legenda)}</div></div>` : ''}${t0 ? `<div class="h-flutua f2"><span class="estrelas">${tIc('star')}${tIc('star')}${tIc('star')}${tIc('star')}${tIc('star')}</span></div>` : ''}</div></div></section>`;
  },
  marquee(c, v) {
    const p = tLista(c.d.palavras, 10); if (!p.length) return '';
    const fila = p.map(x => `<span>${tEsc(x)}</span>`).join('');
    return `<div class="marquee${v === 'cor' ? ' cor' : ''}" aria-hidden="true"><div class="trilho">${fila}${fila}</div></div>`;
  },
  logos(c) {
    const p = tLista(c.d.palavras, 6); if (!p.length) return '';
    return `<section class="s" style="padding:clamp(34px,5vw,56px) 0"><div class="w logos">${p.map(x => `<span><i>${tEsc(tIniciais(x))}</i>${tEsc(x)}</span>`).join('')}</div></section>`;
  },
  numeros(c, v, x) {
    const n = tLista(c.d.numeros, 4); if (!n.length) return '';
    const cls = v === 'cartoes' ? 'num-cartoes' : 'num-faixa';
    return `<section class="s${x.fundo}" ${x.compacto ? 'style="padding:clamp(48px,6vw,80px) 0"' : ''}><div class="w nums ${cls}">${n.map(it => `<div class="num rv"><b data-conta="${tEsc(String(it.valor).replace(/[^\d.,]/g, ''))}">${tEsc(it.valor)}${tEsc(it.sufixo || '')}</b><span>${tEsc(it.legenda)}</span></div>`).join('')}</div></section>`;
  },
  servicos(c, v, x) {
    const s = tLista(c.d.servicos, 6); if (!s.length) return '';
    const cab = tCab(c, x.etq || c.d.textos.servicos_etiqueta, c.d.textos.servicos_titulo, c.d.textos.servicos_texto, { centro: v === 'cartoes' });
    const verMais = x.pagina !== 'servicos' && c.temPagina('servicos') ? `<a class="lnk" href="servicos.html">${tEsc(c.txt.verTodos)}${tIc('arrow-right')}</a>` : '';
    if (v === 'alternado') return `<section class="s${x.fundo}"><div class="w">${cab}<div class="alternado">${s.slice(0, x.pagina === 'servicos' ? 6 : 3).map((it, i) => `<div class="duas rv">${tFoto(c, 'servico-' + (i + 1), it.titulo, '', it.icone)}<div><span class="svc-num">${String(i + 1).padStart(2, '0')}</span><h3>${tEsc(it.titulo)}</h3><p class="lead">${tEsc(it.texto)}</p><ul>${tLista(it.detalhes, 4).map(dd => `<li>${tIc('check')}${tEsc(dd)}</li>`).join('')}</ul>${it.preco ? `<p style="font-weight:800;margin-bottom:18px">${tEsc(it.preco)}</p>` : ''}${tBtnS(c.txt.saberMais, c.ctaPrincipal)}</div></div>`).join('')}</div>${verMais ? `<div style="margin-top:40px">${verMais}</div>` : ''}</div></section>`;
    if (v === 'bento') return `<section class="s${x.fundo}"><div class="w"><div class="s-cab-linha">${cab}${verMais}</div><div class="bento">${s.map((it, i) => `<div class="cartao svc mexe rv">${i === 0 ? tFoto(c, 'servico-1', '', '', it.icone) : ''}<span class="icx">${tIc(it.icone)}</span><h3>${tEsc(it.titulo)}</h3><p>${tEsc(it.texto)}</p>${i === 0 && tLista(it.detalhes).length ? `<ul>${tLista(it.detalhes, 3).map(dd => `<li>${tIc('check')}${tEsc(dd)}</li>`).join('')}</ul>` : ''}</div>`).join('')}</div></div></section>`;
    if (v === 'lista') return `<section class="s${x.fundo}"><div class="w"><div class="s-cab-linha">${cab}${verMais}</div><div class="lista-svc">${s.map((it, i) => `<div class="it rv"><span class="icx">${tIc(it.icone)}</span><h3>${tEsc(it.titulo)}</h3><p class="suave">${tEsc(it.texto)}</p><span class="preco" style="font-weight:800">${tEsc(it.preco || '')}</span></div>`).join('')}</div></div></section>`;
    if (v === 'abas') return `<section class="s${x.fundo}"><div class="w">${cab}<div data-abas><div class="abas-nav" role="tablist">${s.map((it, i) => `<button type="button" role="tab" aria-selected="${i === 0}">${tEsc(it.titulo)}</button>`).join('')}</div>${s.map((it, i) => `<div class="aba" role="tabpanel"${i ? ' hidden' : ''}><div class="duas">${tFoto(c, 'servico-' + (i + 1), it.titulo, '', it.icone)}<div><span class="icx">${tIc(it.icone)}</span><h3 style="font-size:clamp(26px,3vw,36px);margin:18px 0 12px">${tEsc(it.titulo)}</h3><p class="lead">${tEsc(it.texto)}</p><ul class="vistos" style="margin:22px 0">${tLista(it.detalhes, 4).map(dd => `<li>${tIc('circle-check')}<span>${tEsc(dd)}</span></li>`).join('')}</ul>${it.preco ? `<p style="font-weight:800">${tEsc(it.preco)}</p>` : ''}</div></div></div>`).join('')}</div></div></section>`;
    // cartoes
    return `<section class="s${x.fundo}"><div class="w">${cab}<div class="grid g3">${s.map(it => `<div class="cartao svc mexe rv"><span class="icx">${tIc(it.icone)}</span><h3>${tEsc(it.titulo)}</h3><p>${tEsc(it.texto)}</p>${tLista(it.detalhes).length ? `<ul>${tLista(it.detalhes, 3).map(dd => `<li>${tIc('check')}${tEsc(dd)}</li>`).join('')}</ul>` : ''}${it.preco ? `<div class="rodape-svc"><span class="preco">${tEsc(it.preco)}</span><a class="lnk" href="${tEsc(c.ctaPrincipal)}">${tIc('arrow-right')}</a></div>` : ''}</div>`).join('')}</div>${verMais ? `<div style="margin-top:36px;text-align:center">${verMais}</div>` : ''}</div></section>`;
  },
  beneficios(c, v, x) {
    const b = tLista(c.d.beneficios, 6); if (!b.length) return '';
    const cab = tCab(c, c.d.textos.beneficios_etiqueta, c.d.textos.beneficios_titulo, c.d.textos.beneficios_texto, { centro: v !== 'lista' });
    if (v === 'lista') return `<section class="s${x.fundo}"><div class="w sticky-duas"><div>${cab}<ul class="vistos">${b.map(it => `<li class="rv">${tIc(it.icone, 'circle-check')}<div><b>${tEsc(it.titulo)}</b><span class="suave">${tEsc(it.texto)}</span></div></li>`).join('')}</ul></div><div class="cartao fixo rv">${tFoto(c, 'sobre', '', '', c.icone)}<h3 style="font-size:24px;margin:20px 0 10px">${tEsc((c.d.cta && c.d.cta.titulo) || '')}</h3><p class="suave" style="margin-bottom:20px">${tEsc((c.d.cta && c.d.cta.texto) || '')}</p>${tBtnP((c.d.cta && c.d.cta.botao) || c.d.hero.botao, c.ctaPrincipal)}</div></div></section>`;
    return `<section class="s${x.fundo}"><div class="w">${cab}<div class="grid g3">${b.map(it => `<div class="bnf rv"><span class="icx">${tIc(it.icone)}</span><div><h3>${tEsc(it.titulo)}</h3><p>${tEsc(it.texto)}</p></div></div>`).join('')}</div></div></section>`;
  },
  sobre(c, v, x) {
    const s = c.d.sobre || {};
    const textos = `<p class="lead">${tEsc(s.texto)}</p>${s.texto2 ? `<p class="suave">${tEsc(s.texto2)}</p>` : ''}`;
    const link = x.pagina !== 'sobre' && c.temPagina('sobre') ? `<div style="margin-top:28px">${tBtnS(c.txt.historia, 'sobre.html', 'arrow-right')}</div>` : '';
    if (v === 'editorial') return `<section class="s${x.fundo}"><div class="w ed-cols"><div class="rv">${tEtq(s.etiqueta)}<h2 style="margin-top:16px">${tEsc(s.titulo)}</h2></div><div class="rv"><div class="txt"><p class="lead">${tEsc(s.texto)}</p>${s.texto2 ? `<p class="suave">${tEsc(s.texto2)}</p>` : ''}${s.missao ? `<p class="suave">${tEsc(s.missao)}</p>` : ''}</div>${link}</div></div>${x.pagina === 'sobre' && tLista(s.marcos).length ? `<div class="w marcos">${tLista(s.marcos, 4).map(m => `<div class="marco rv"><b>${tEsc(m.ano)}</b><p class="suave">${tEsc(m.texto)}</p></div>`).join('')}</div>` : ''}</section>`;
    if (v === 'citacao') return `<section class="s${x.fundo}"><div class="w"><blockquote class="citacao rv" style="margin:0">${tIc('quote')}${tEsc(s.citacao || s.titulo)}<cite>${tEsc(s.autor || c.d.marca.nome)}</cite></blockquote></div></section>`;
    // foto-lado
    return `<section class="s${x.fundo} sobre"><div class="w duas"><div class="foto-par rv">${tFoto(c, 'sobre', c.d.marca.nome)}${c.fotoDe('galeria-3') ? tFoto(c, 'galeria-3', '', 'mini') : ''}</div><div class="rv">${tEtq(s.etiqueta)}<h2>${tEsc(s.titulo)}</h2>${textos}<div class="vals">${tLista(s.valores, 3).map(vl => `<div class="val"><span class="icx">${tIc(vl.icone)}</span><div><h4>${tEsc(vl.titulo)}</h4><p class="suave">${tEsc(vl.texto)}</p></div></div>`).join('')}</div>${link}</div></div></section>`;
  },
  valores(c, v, x) {
    const vl = tLista(c.d.sobre && c.d.sobre.valores, 4); if (!vl.length) return '';
    return `<section class="s${x.fundo}"><div class="w">${tCab(c, c.txt.valores, (c.d.sobre && c.d.sobre.missao) || '', '', { centro: true })}<div class="grid g3">${vl.map(it => `<div class="cartao rv"><span class="icx">${tIc(it.icone)}</span><h3 style="font-size:21px;margin:18px 0 8px">${tEsc(it.titulo)}</h3><p class="suave">${tEsc(it.texto)}</p></div>`).join('')}</div></div></section>`;
  },
  processo(c, v, x) {
    const p = tLista(c.d.processo, 5); if (!p.length) return '';
    const cab = tCab(c, c.d.textos.processo_etiqueta, c.d.textos.processo_titulo, c.d.textos.processo_texto, { centro: v === 'circulos' });
    if (v === 'timeline') return `<section class="s${x.fundo}"><div class="w duas" style="align-items:start">${cab}<div class="tl">${p.map((it, i) => `<div class="tl-it rv"><b>${i + 1}</b><div><h3>${tEsc(it.titulo)}</h3><p>${tEsc(it.texto)}</p></div></div>`).join('')}</div></div></section>`;
    if (v === 'circulos') return `<section class="s${x.fundo}"><div class="w">${cab}<div class="circs">${p.map((it, i) => `<div class="c rv"><i>${i + 1}</i><h3>${tEsc(it.titulo)}</h3><p>${tEsc(it.texto)}</p></div>`).join('')}</div></div></section>`;
    return `<section class="s${x.fundo}"><div class="w">${cab}<div class="passos">${p.map(it => `<div class="passo rv"><h3>${tEsc(it.titulo)}</h3><p>${tEsc(it.texto)}</p></div>`).join('')}</div></div></section>`;
  },
  publico(c, v, x) {
    const p = tLista(c.d.publico, 4); if (!p.length) return '';
    return `<section class="s${x.fundo}"><div class="w">${tCab(c, c.txt.para, c.d.textos.publico_titulo || '', '', { centro: true })}<div class="grid g3">${p.map(it => `<div class="cartao perfil-c mexe rv"><span class="icx">${tIc(it.icone, 'user')}</span><h3>${tEsc(it.titulo)}</h3><p>${tEsc(it.texto)}</p></div>`).join('')}</div></div></section>`;
  },
  testemunhos(c, v, x) {
    const t = tLista(c.d.testemunhos, 6); if (!t.length) return '';
    const est = `<span class="estrelas">${tIc('star')}${tIc('star')}${tIc('star')}${tIc('star')}${tIc('star')}</span>`;
    const card = it => `<div class="cartao dep rv">${est}<blockquote>“${tEsc(it.texto)}”</blockquote><div class="quem"><span class="av">${tEsc(tIniciais(it.nome))}</span><div><b>${tEsc(it.nome)}</b><small>${tEsc([it.papel, it.cidade].filter(Boolean).join(' · '))}</small></div></div></div>`;
    const cab = tCab(c, c.txt.clientes, c.d.textos.testemunhos_titulo || '', '', { centro: v === 'cartoes' });
    if (v === 'destaque') { const [a, ...r] = t; return `<section class="s${x.fundo}"><div class="w">${cab}<div class="dep-grande"><blockquote class="citacao rv" style="margin:0">${tIc('quote')}${tEsc(a.texto)}<cite><b>${tEsc(a.nome)}</b> · ${tEsc([a.papel, a.cidade].filter(Boolean).join(', '))}</cite></blockquote><div class="dep-lado">${r.slice(0, 2).map(card).join('')}</div></div></div></section>`; }
    if (v === 'carrossel') return `<section class="s${x.fundo}"><div class="w" data-carrossel><div class="s-cab-linha">${cab}<div class="setas"><button type="button" data-ir="-1" aria-label="${tEsc(c.txt.anterior)}">${tIc('arrow-left')}</button><button type="button" data-ir="1" aria-label="${tEsc(c.txt.seguinte)}">${tIc('arrow-right')}</button></div></div><div class="carrossel">${t.map(card).join('')}</div></div></section>`;
    return `<section class="s${x.fundo}"><div class="w">${cab}<div class="grid g3">${t.slice(0, 3).map(card).join('')}</div></div></section>`;
  },
  precos(c, v, x) {
    const p = tLista(c.d.precos, 4); if (!p.length) return '';
    return `<section class="s${x.fundo}"><div class="w">${tCab(c, c.d.textos.precos_etiqueta, c.d.textos.precos_titulo, c.d.textos.precos_texto, { centro: true })}<div class="precos">${p.map(it => `<div class="cartao plano${it.destaque ? ' dest' : ''} rv">${it.destaque ? `<span class="selo">${tEsc(c.txt.popular)}</span>` : ''}<h3>${tEsc(it.nome)}</h3><p class="desc">${tEsc(it.descricao)}</p><div class="valor">${tEsc(it.preco)} <small>${tEsc(it.periodo || '')}</small></div><ul>${tLista(it.itens, 7).map(i => `<li>${tIc('check')}${tEsc(i)}</li>`).join('')}</ul>${it.destaque ? tBtnP(it.botao || c.d.hero.botao, c.ctaPrincipal) : `<a class="btn btn-s" href="${tEsc(c.ctaPrincipal)}">${tEsc(it.botao || c.d.hero.botao || '')}</a>`}</div>`).join('')}</div></div></section>`;
  },
  comparacao(c, v, x) {
    const cp = c.d.comparacao || {}; const l = tLista(cp.linhas, 8); if (!l.length) return '';
    const m = b => b ? `<span class="sim">${tIc('circle-check')}</span>` : `<span class="nao">${tIc('x')}</span>`;
    return `<section class="s${x.fundo}"><div class="w">${tCab(c, '', c.d.textos.comparacao_titulo || '', '', { centro: true })}<div class="comp rv"><table><thead><tr><th></th><th>${tEsc(cp.nos || c.d.marca.nome)}</th><th>${tEsc(cp.outros || c.txt.outros)}</th></tr></thead><tbody>${l.map(r => `<tr><td>${tEsc(r.item)}</td><td>${m(r.nos !== false)}</td><td>${m(!!r.outros)}</td></tr>`).join('')}</tbody></table></div></div></section>`;
  },
  garantia(c, v, x) {
    const g = c.d.garantia || {}; if (!g.titulo) return '';
    return `<section class="s${x.fundo}"><div class="w garantia rv"><div class="selo"><div>${tIc('shield-check')}<b>${tEsc(c.txt.garantia)}</b></div></div><div><h2>${tEsc(g.titulo)}</h2><p class="lead">${tEsc(g.texto)}</p></div></div></section>`;
  },
  faq(c, v, x) {
    const f = tLista(c.d.faq, 8); if (!f.length) return '';
    const lista = `<div class="faq">${f.map((it, i) => `<details class="rv"${i === 0 ? ' open' : ''}><summary>${tEsc(it.pergunta)}${tIc('plus')}</summary><p>${tEsc(it.resposta)}</p></details>`).join('')}</div>`;
    const cab = tCab(c, c.txt.faq, c.d.textos.faq_titulo || c.txt.faq, c.d.textos.faq_texto, { centro: v !== 'duas' });
    if (v === 'duas') return `<section class="s${x.fundo}"><div class="w faq-duas"><div>${cab}${c.temPagina('contacto') ? tBtnS(c.txt.escreve, 'contacto.html', 'message-circle') : ''}</div>${lista}</div></section>`;
    return `<section class="s${x.fundo}"><div class="w" style="max-width:860px">${cab}${lista}</div></section>`;
  },
  cta(c, v, x) {
    const k = c.d.cta || {}; if (!k.titulo) return '';
    const wa = tBtnS(c.txt.whatsapp, tWa(c), 'message-circle');
    if (v === 'foto') return `<section class="s${x.fundo}"><div class="w"><div class="cta-foto rv">${tFoto(c, x.foto || 'galeria-4', '')}<h2>${tEsc(k.titulo)}</h2><p>${tEsc(k.texto)}</p><div class="btns">${tBtnP(k.botao, c.ctaPrincipal)}${wa}</div></div></div></section>`;
    if (v === 'cartao') return `<section class="s${x.fundo}"><div class="w"><div class="cta-cartao rv"><div><h2>${tEsc(k.titulo)}</h2><p>${tEsc(k.texto)}</p></div><div class="btns">${tBtnP(k.botao, c.ctaPrincipal)}${wa}</div></div></div></section>`;
    return `<section class="s ${x.cor || 'escura'}"><div class="w cta-faixa rv"><div><h2>${tEsc(k.titulo)}</h2><p>${tEsc(k.texto)}</p></div><div class="btns">${tBtnP(k.botao, c.ctaPrincipal)}${wa}</div></div></section>`;
  },
  galeria(c, v, x) {
    const leg = tLista(c.d.galeria, 9); const n = Math.max(6, leg.length);
    const usos = Array.from({ length: Math.min(n, 9) }, (_, i) => 'galeria-' + (i + 1));
    const cab = tCab(c, c.d.textos.galeria_etiqueta, c.d.textos.galeria_titulo || '', '', {});
    if (v === 'grelha') return `<section class="s${x.fundo}"><div class="w">${cab}<div class="grelha-fotos">${usos.map((u, i) => `<div class="rv">${tFoto(c, u, leg[i] || '')}</div>`).join('')}</div></div></section>`;
    return `<section class="s${x.fundo}"><div class="w">${cab}<div class="masonry">${usos.map((u, i) => `<figure class="rv">${tFoto(c, u, leg[i] || '')}${leg[i] ? `<figcaption>${tEsc(leg[i])}</figcaption>` : ''}</figure>`).join('')}</div></div></section>`;
  },
  equipa(c, v, x) {
    const e = tLista(c.d.equipa, 4); if (!e.length) return '';
    return `<section class="s${x.fundo}"><div class="w">${tCab(c, c.txt.equipa, c.d.textos.equipa_titulo || '', '', {})}<div class="grid g4">${e.map((p, i) => `<div class="pessoa rv">${c.fotoDe('equipa-' + (i + 1)) ? tFoto(c, 'equipa-' + (i + 1), p.nome) : `<div class="mono">${tEsc(tIniciais(p.nome))}</div>`}<h3>${tEsc(p.nome)}</h3><small>${tEsc(p.funcao)}</small><p>${tEsc(p.frase)}</p></div>`).join('')}</div></div></section>`;
  },
  menu(c, v, x) {
    const m = tLista(c.d.menu, 5); if (!m.length) return '';
    const corpo = m.map(cat => `<div class="menu-cat rv"><h3>${tEsc(cat.categoria)}</h3>${tLista(cat.itens, 8).map(it => `<div class="menu-it"><b>${tEsc(it.nome)}</b><span>${tEsc(it.preco)}</span>${it.descricao ? `<p>${tEsc(it.descricao)}</p>` : ''}</div>`).join('')}</div>`).join('');
    const link = x.pagina !== 'menu' && c.temPagina('menu') ? `<a class="lnk" href="menu.html">${tEsc(c.txt.verTodos)}${tIc('arrow-right')}</a>` : '';
    return `<section class="s${x.fundo}"><div class="w"><div class="s-cab-linha">${tCab(c, c.d.textos.menu_etiqueta, c.d.textos.menu_titulo || '', c.d.textos.menu_texto, {})}${link}</div><div class="menu-duas">${corpo}</div></div></section>`;
  },
  inclui(c, v, x) {
    const vd = c.d.venda || {}; const l = tLista(vd.inclui, 8); if (!l.length) return '';
    return `<section class="s${x.fundo}"><div class="w">${tCab(c, c.txt.inclui, vd.titulo_inclui || vd.produto || '', vd.para_quem, { centro: true })}<ul class="vistos inclui">${l.map(it => `<li class="rv">${tIc('circle-check')}<span>${tEsc(it)}</span></li>`).join('')}</ul>${tLista(vd.bonus).length ? `<div class="bonus" style="margin-top:28px">${tLista(vd.bonus, 3).map((b, i) => `<div class="cartao rv"><small>${tEsc(c.txt.bonus)} ${i + 1}</small><h3 style="font-size:19px">${tEsc(b)}</h3></div>`).join('')}</div>` : ''}</div></section>`;
  },
  contacto(c, v, x) {
    const k = c.d.contacto || {};
    const linhas = [
      k.telefone && `<a href="tel:${tEsc(String(k.telefone).replace(/\s+/g, ''))}"><span class="icx">${tIc('phone')}</span><span><small>${tEsc(c.txt.telefone)}</small><b>${tEsc(k.telefone)}</b></span></a>`,
      (k.whatsapp || k.telefone) && `<a href="${tEsc(tWa(c))}" target="_blank" rel="noopener"><span class="icx">${tIc('message-circle')}</span><span><small>${tEsc(c.txt.whatsapp)}</small><b>${tEsc(k.whatsapp || k.telefone)}</b></span></a>`,
      k.email && `<a href="mailto:${tEsc(k.email)}"><span class="icx">${tIc('mail')}</span><span><small>${tEsc(c.txt.email)}</small><b>${tEsc(k.email)}</b></span></a>`,
      k.morada && `<div><span class="icx">${tIc('map-pin')}</span><span><small>${tEsc(c.txt.morada)}</small><b>${tEsc(k.morada)}</b></span></div>`
    ].filter(Boolean).join('');
    const hor = tLista(k.horario, 4);
    const horario = hor.length ? `<div class="cartao" style="margin-top:14px"><span class="estado-aberto">${tIc('clock')}<span>${tEsc(c.txt.horario)}</span></span><div class="horario">${hor.map(h => `<div><span>${tEsc(h.dias)}</span><b>${tEsc(h.horas)}</b></div>`).join('')}</div></div>` : '';
    const mapa = `<div class="mapa rv"><svg class="ruas" viewBox="0 0 400 300" preserveAspectRatio="xMidYMid slice" fill="none" stroke="currentColor" stroke-width="6"><path d="M-10 70 Q120 90 210 40 T420 60"/><path d="M-10 210 Q140 180 230 230 T420 200"/><path d="M90 -10 Q110 120 70 310"/><path d="M290 -10 Q260 150 320 310"/><path d="M-10 140 H420" stroke-width="10" opacity=".7"/><path d="M180 -10 V310" stroke-width="3" stroke-dasharray="10 10"/></svg><div class="pin"><i>${tIc('map-pin')}</i><span>${tEsc(k.cidade || k.morada || c.d.marca.nome)}</span></div></div>`;
    const modulo = x.pagina === 'contacto' ? `<div style="margin-top:20px"><div id="daniel-ia-contacto" data-aberto="1"></div></div>` : '';
    return `<section class="s${x.fundo}"><div class="w">${x.pagina === 'contacto' ? '' : tCab(c, c.txt.contactos, c.d.textos.contacto_titulo || '', c.d.textos.contacto_texto, {})}<div class="ctt"><div><div class="ctt-lista rv">${linhas}</div>${horario}</div><div>${mapa}${modulo}</div></div></div></section>`;
  },
  whatsapp(c, v, x) {
    const k = c.d.cta || {};
    return `<section class="s${x.fundo}" style="padding:clamp(40px,6vw,70px) 0"><div class="w"><div class="wa-faixa rv"><span class="icx">${tIc('message-circle')}</span><div><h3>${tEsc(k.titulo || c.d.marca.nome)}</h3><p>${tEsc(k.texto || '')}</p></div><a class="btn btn-p" href="${tEsc(tWa(c))}" target="_blank" rel="noopener">${tEsc(c.txt.whatsapp)}${tIc('arrow-up-right')}</a></div></div></section>`;
  },
  modulo(c, v, x) {
    const ids = { loja: 'daniel-ia-produtos', portfolio: 'daniel-ia-portfolio', galeria: 'daniel-ia-galeria', blog: 'daniel-ia-blog' };
    const id = ids[v] || 'daniel-ia-produtos';
    const pg = { loja: 'loja', portfolio: 'trabalhos', galeria: 'albuns', blog: 'artigos' }[v];
    const titulo = { loja: c.d.textos.loja_titulo || c.txt.produtos, portfolio: c.d.textos.portfolio_titulo || c.txt.trabalhos, galeria: c.d.textos.galeria_titulo || c.txt.albuns, blog: c.d.textos.blog_titulo || c.txt.artigos }[v];
    const ancora = v === 'loja' ? ' id="oferta"' : '';
    const extra = v === 'loja' ? ' data-sem-capa="1"' : '';
    const cab = (v === 'loja' && c.tipo === 'E-commerce') ? '' : `<div class="s-cab-linha">${tCab(c, '', titulo, '', {})}${c.temPagina(pg) ? `<a class="lnk" href="${pg}.html">${tEsc(c.txt.verTodos)}${tIc('arrow-right')}</a>` : ''}</div>`;
    return `<section class="s s-modulo${x.fundo}"${ancora} style="${v === 'loja' && c.tipo === 'E-commerce' ? 'padding-top:clamp(24px,3vw,40px)' : ''}"><div class="w">${cab}<div id="${id}"${extra}></div></div></section>`;
  },
  quiz(c) { return `<section class="s s-quiz"><div class="w"><div id="daniel-ia-quiz"></div></div></section>`; },
  topo(c, v, x) {
    const pg = (c.d.paginas && c.d.paginas[x.pagina]) || {};
    const pl = (c.plano || []).find(p => p.slug === x.pagina) || {};
    const titulo = pg.titulo || pl.titulo || '';
    const sub = pg.subtitulo || pl.subtitulo || '';
    const mig = `<nav class="mig" aria-label="breadcrumb"><a href="index.html">${tEsc(c.txt.inicio)}</a><span>/</span><span>${tEsc(pl.nav || titulo)}</span></nav>`;
    if (v === 'foto') return `<section class="topo-pg v-foto">${tFoto(c, x.foto || 'sobre', '')}<div class="w rv">${mig}<h1>${tEsc(titulo)}</h1>${sub ? `<p class="lead">${tEsc(sub)}</p>` : ''}</div></section>`;
    return `<section class="topo-pg v-${v === 'centrado' ? 'centrado' : 'simples'}"><div class="w rv">${mig}<h1>${tEsc(titulo)}</h1>${sub ? `<p class="lead">${tEsc(sub)}</p>` : ''}</div></section>`;
  }
};

// Páginas interiores: receita base por página (as variantes vêm do template).
function tReceitaPagina(slug, t) {
  const v = t.variantes || {};
  const topo = 'topo:' + (v.topo || 'simples');
  const r = {
    sobre: [topo, 'sobre:' + (v.sobre_pagina || 'editorial'), 'numeros:' + (v.numeros || 'faixa'), 'valores', 'equipa', 'testemunhos:' + (v.testemunhos || 'cartoes'), 'cta:' + (v.cta || 'cartao')],
    servicos: [topo, 'servicos:' + (v.servicos_pagina || 'alternado'), 'processo:' + (v.processo || 'passos'), 'faq:simples', 'cta:' + (v.cta || 'cartao')],
    processo: [topo, 'processo:timeline', 'beneficios:lista', 'garantia', 'cta:' + (v.cta || 'cartao')],
    precos: [topo, 'precos', 'comparacao', 'faq:duas', 'cta:' + (v.cta || 'cartao')],
    testemunhos: [topo, 'testemunhos:destaque', 'numeros:cartoes', 'testemunhos:carrossel', 'cta:' + (v.cta || 'cartao')],
    perguntas: [topo, 'faq:simples', 'whatsapp', 'cta:' + (v.cta || 'cartao')],
    equipa: [topo, 'equipa', 'valores', 'cta:' + (v.cta || 'cartao')],
    galeria: [topo, 'galeria:masonry', 'cta:' + (v.cta || 'foto')],
    menu: [topo, 'menu', 'whatsapp', 'cta:' + (v.cta || 'foto')],
    reservas: [topo, 'processo:circulos', 'contacto', 'faq:simples'],
    contacto: [topo, 'contacto', 'faq:duas']
  };
  return (t.paginas_receitas && t.paginas_receitas[slug]) || r[slug] || [topo, 'sobre:editorial', 'cta:cartao'];
}

// Monta o <main> de uma página a partir da lista de secções.
function tMontarSeccoes(c, lista, pagina) {
  let alt = false;
  return lista.map(item => {
    const [tipo, variante] = String(item).split(':');
    const fn = TPL_SECCOES[tipo]; if (!fn) return '';
    const neutra = !['hero', 'marquee', 'topo', 'cta', 'quiz', 'logos'].includes(tipo) && !(tipo === 'numeros' && variante === 'faixa');
    let fundo = '';
    if (neutra) { if (alt) fundo = ' alt'; alt = !alt; }
    if (tipo === 'numeros' && variante === 'faixa') fundo = ' ' + ((c.t.variantes && c.t.variantes.numeros_cor) || 'escura');
    return fn(c, variante, { fundo, pagina });
  }).join('\n');
}

// ======================================================
// Templates prontos (1.60.0) - montar o site, preencher com IA, rotas
// ======================================================
// Letras do Google Fonts que os templates podem usar (eixo de pesos).
const TPL_FONTES = {
  'Inter': 'wght@400;500;600;700;800', 'Manrope': 'wght@400;500;600;700;800', 'Plus Jakarta Sans': 'wght@400;500;600;700;800',
  'DM Sans': 'wght@400;500;600;700;800', 'Outfit': 'wght@400;500;600;700;800', 'Sora': 'wght@400;500;600;700;800',
  'Space Grotesk': 'wght@400;500;600;700', 'Syne': 'wght@400;500;600;700;800', 'Unbounded': 'wght@400;500;600;700;800',
  'Archivo': 'wght@400;500;600;700;800;900', 'Bricolage Grotesque': 'wght@400;500;600;700;800', 'Fraunces': 'wght@400;500;600;700;800',
  'Playfair Display': 'wght@400;500;600;700;800', 'Cormorant Garamond': 'wght@400;500;600;700', 'Lora': 'wght@400;500;600;700',
  'Libre Baskerville': 'wght@400;700', 'Oswald': 'wght@400;500;600;700', 'Montserrat': 'wght@400;500;600;700;800;900',
  'Poppins': 'wght@400;500;600;700;800', 'Raleway': 'wght@400;500;600;700;800', 'Work Sans': 'wght@400;500;600;700;800',
  'Lexend': 'wght@400;500;600;700;800', 'Figtree': 'wght@400;500;600;700;800', 'Urbanist': 'wght@400;500;600;700;800',
  'Epilogue': 'wght@400;500;600;700;800', 'Nunito': 'wght@400;500;600;700;800', 'Rubik': 'wght@400;500;600;700;800',
  'Merriweather': 'wght@400;700;900', 'EB Garamond': 'wght@400;500;600;700;800', 'Bodoni Moda': 'wght@400;500;600;700;800',
  'DM Serif Display': '', 'Instrument Serif': '', 'Bebas Neue': '', 'Anton': '', 'Gloock': '', 'Young Serif': '', 'Abril Fatface': '',
  'Caveat': 'wght@400;500;600;700', 'Pacifico': ''
};
function tFonteUrl(lista) {
  const fams = [...new Set(lista.filter(f => f && f in TPL_FONTES))];
  if (!fams.length) return '';
  return 'https://fonts.googleapis.com/css2?' + fams.map(f => 'family=' + f.replace(/ /g, '+') + (TPL_FONTES[f] ? ':' + TPL_FONTES[f] : '')).join('&') + '&display=swap';
}
// Fichas do template -> :root (com valores por omissão bons)
function tFichas(t) {
  const m = Object.assign({}, t.tema || {});
  const f = t.fontes || {};
  const titulos = f.titulos in TPL_FONTES ? f.titulos : 'Sora';
  const texto = f.texto in TPL_FONTES ? f.texto : 'Inter';
  const umPeso = TPL_FONTES[titulos] === '';
  const v = {
    '--dia-fundo': m.fundo || '#ffffff', '--dia-superficie': m.superficie || '#ffffff', '--dia-texto': m.texto || '#121212',
    '--dia-texto-suave': m.suave || '#5b5b5b', '--dia-primaria': m.primaria || '#2f5bff', '--dia-primaria-texto': m.primariaTexto || '#ffffff',
    '--dia-borda': m.borda || 'rgba(0,0,0,.09)', '--dia-raio': m.raio || '16px',
    '--dia-fonte-titulos': `'${titulos}'`, '--dia-fonte-texto': `'${texto}'`,
    '--t-fundo2': m.fundo2 || '#f5f5f3', '--t-destaque': m.destaque || m.primaria || '#ff7a45',
    '--t-escuro': m.escuro || '#111111', '--t-escuro-texto': m.escuroTexto || '#f5f5f5', '--t-escuro-suave': m.escuroSuave || 'rgba(255,255,255,.72)',
    '--t-cab-fundo': m.cabFundo || m.fundo || '#ffffff', '--t-cab-texto': m.cabTexto || m.texto || '#121212', '--t-cab-borda': m.cabBorda || m.borda || 'rgba(0,0,0,.08)',
    '--t-rod-fundo': m.rodFundo || m.escuro || '#111111', '--t-rod-texto': m.rodTexto || m.escuroTexto || '#f5f5f5',
    '--t-etq-cor': m.etq || m.primaria || '#2f5bff',
    '--t-raio-foto': m.raioFoto || `calc(${m.raio || '16px'} * 1.4)`, '--t-raio-btn': m.raioBtn || '999px',
    '--t-borda': m.bordaLargura || '1px', '--t-sombra': m.sombra || 'none', '--t-max': m.max || '1200px',
    '--t-espaco': m.espaco || 'clamp(68px,9vw,128px)',
    '--t-titulo-peso': String(umPeso ? 400 : (m.tituloPeso || 700)), '--t-titulo-caixa': m.tituloCaixa || 'none',
    '--t-titulo-espaco': m.tituloEspaco || '-0.025em',
    '--t-dest-estilo': m.destEstilo || 'normal', '--t-dest-cor': m.destCor || m.primaria || 'inherit',
    '--t-dest-fonte': m.destFonte ? `'${m.destFonte}'` : 'inherit'
  };
  return ':root{' + Object.entries(v).map(([k, x]) => k + ':' + String(x).replace(/[;{}<>]/g, '')).join(';') + '}';
}

// JavaScript dos templates: o conteúdo é sempre visível sem ele.
const TPL_JS = `(function(){
var d=document,h=d.documentElement;
function todos(s,r){return Array.prototype.slice.call((r||d).querySelectorAll(s));}
var cab=d.querySelector('.cab'),bg=d.querySelector('.burger');
if(bg&&cab){bg.addEventListener('click',function(){var a=cab.classList.toggle('aberto');bg.setAttribute('aria-expanded',a?'true':'false');d.body.style.overflow=a?'hidden':'';});
todos('.nav a',cab).forEach(function(a){a.addEventListener('click',function(){cab.classList.remove('aberto');d.body.style.overflow='';});});}
var rv=todos('.rv');
if('IntersectionObserver' in window){var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('on');io.unobserve(e.target);}});},{rootMargin:'0px 0px -8% 0px'});rv.forEach(function(e){io.observe(e);});}
else rv.forEach(function(e){e.classList.add('on');});
setTimeout(function(){rv.forEach(function(e){e.classList.add('on');});},2600);
todos('[data-conta]').forEach(function(b){var alvo=parseFloat(String(b.getAttribute('data-conta')).replace(',','.'));if(!alvo||alvo>100000)return;var fim=b.textContent,inteiro=alvo%1===0,suf=fim.replace(/^[\\d.,\\s]+/,'');var ok=false;
var ob=('IntersectionObserver' in window)?new IntersectionObserver(function(es){if(!es[0].isIntersecting||ok)return;ok=true;ob.disconnect();var t0=null;function p(t){if(!t0)t0=t;var k=Math.min(1,(t-t0)/1400),v=alvo*(1-Math.pow(1-k,3));b.textContent=(inteiro?Math.round(v):v.toFixed(1))+suf;if(k<1)requestAnimationFrame(p);else b.textContent=fim;}requestAnimationFrame(p);}):null;if(ob)ob.observe(b);});
todos('[data-abas]').forEach(function(w){var bs=todos('[role=tab]',w),ps=todos('[role=tabpanel]',w);bs.forEach(function(b,i){b.addEventListener('click',function(){bs.forEach(function(x,j){x.setAttribute('aria-selected',j===i?'true':'false');ps[j].hidden=j!==i;});});});});
todos('[data-carrossel]').forEach(function(w){var tr=w.querySelector('.carrossel');todos('[data-ir]',w).forEach(function(b){b.addEventListener('click',function(){tr.scrollBy({left:(tr.clientWidth*0.8)*parseInt(b.getAttribute('data-ir'),10),behavior:'smooth'});});});});
})();`;

function tNormalizar(dd, nome) {
  const d = Object.assign({}, dd || {});
  d.marca = Object.assign({ nome: nome || '', slogan: '', descricao: '' }, d.marca || {});
  if (nome) d.marca.nome = nome;
  d.hero = Object.assign({}, d.hero || {});
  d.textos = Object.assign({}, d.textos || {});
  d.sobre = Object.assign({}, d.sobre || {});
  d.contacto = Object.assign({}, d.contacto || {});
  d.cta = Object.assign({}, d.cta || {});
  d.paginas = Object.assign({}, d.paginas || {});
  return d;
}

// Contexto de montagem: template + conteúdo + fotos + páginas
function tContexto({ t, conteudo, fotos, idioma, logoUrl, plano, quiz, nome }) {
  const lingua = normalizarIdioma(idioma);
  const d = tNormalizar(conteudo, nome);
  const mapa = {};
  (fotos || []).forEach(f => { if (f && f.uso && f.url && !mapa[f.uso]) mapa[f.uso] = f.url; });
  const usosPedidos = new Set();
  const temPagina = slug => (plano || []).some(p => p.slug === slug && p.menu !== false);
  const tipo = t.tipo;
  const c = {
    t, d, idioma: lingua, txt: TPL_TXT[lingua] || TPL_TXT.pt, logoUrl: logoUrl || '', plano: plano || [], quiz: !!quiz, tipo,
    icone: (t.icone && ICONES_LUCIDE[t.icone]) ? t.icone : 'sparkles', usosPedidos, temPagina,
    fotoDe(uso) {
      usosPedidos.add(uso);
      if (mapa[uso]) return mapa[uso];
      const m = /^(servico|galeria|equipa)-(\d+)$/.exec(uso);
      if (m && m[1] === 'servico') return mapa['galeria-' + m[2]] || '';
      return '';
    }
  };
  c.ctaPrincipal = tipo === 'Checkout' ? '#oferta' : tipo === 'E-commerce' ? (temPagina('loja') ? 'loja.html' : '#oferta')
    : temPagina('reservas') ? 'reservas.html' : temPagina('contacto') ? 'contacto.html' : '#contacto';
  c.ctaSecundario = temPagina('servicos') ? 'servicos.html' : temPagina('menu') ? 'menu.html' : temPagina('trabalhos') ? 'trabalhos.html'
    : temPagina('albuns') ? 'albuns.html' : temPagina('artigos') ? 'artigos.html' : temPagina('sobre') ? 'sobre.html' : '#';
  return c;
}

function tCabecalho(c) {
  const v = c.t.cabecalho || 'classico';
  const d = c.d;
  const marca = `<a class="marca" href="index.html">${c.logoUrl ? `<img src="${tEsc(c.logoUrl)}" alt="${tEsc(d.marca.nome)}">` : `<i>${tEsc(tIniciais(d.marca.nome).slice(0, 1))}</i><span>${tEsc(d.marca.nome)}</span>`}</a>`;
  const links = c.plano.filter(p => p.menu !== false).map(p => `<a href="${tEsc(p.ficheiro)}">${tEsc(p.nav)}</a>`).join('');
  const loja = c.tipo === 'E-commerce' || (c.tipo === 'Checkout' && c.t.carrinho);
  const acao = loja
    ? `<button class="cab-carrinho" type="button" data-dia-carrinho aria-label="${tEsc(c.txt.carrinho)}">${tIc('shopping-bag')}<span data-dia-carrinho-contagem>0</span></button>`
    : `<a class="btn btn-p" href="${tEsc(c.ctaPrincipal)}">${tEsc(d.hero.botao || c.txt.contactos)}</a>`;
  const burger = `<button class="burger" type="button" aria-label="${tEsc(c.txt.menu)}" aria-expanded="false">${svgIcone('menu', 'ic-abrir')}${svgIcone('x', 'ic-fechar')}</button>`;
  const k = d.contacto || {};
  const barra = v === 'barra' ? `<div class="cab-barra"><div class="w">${k.telefone ? `<span>${tIc('phone')}${tEsc(k.telefone)}</span>` : ''}${k.email ? `<span>${tIc('mail')}${tEsc(k.email)}</span>` : ''}<span>${tIc('clock')}${tEsc((tLista(k.horario)[0] && (k.horario[0].dias + ' · ' + k.horario[0].horas)) || d.marca.slogan || '')}</span></div></div>` : '';
  const cls = { classico: 'cab', centrado: 'cab cab-centrado', pilula: 'cab cab-pilula', barra: 'cab', escuro: 'cab' }[v] || 'cab';
  return `<header data-dia="cabecalho" class="${cls}">${barra}<div class="w cab-in">${marca}<nav class="nav" aria-label="${tEsc(c.txt.paginas)}">${links}</nav><div class="cab-acoes">${acao}${burger}</div></div></header>`;
}

function tRodape(c) {
  const v = c.t.rodape || 'colunas';
  const d = c.d, k = d.contacto || {};
  const ano = new Date().getFullYear();
  const links = c.plano.filter(p => p.menu !== false).map(p => `<li><a href="${tEsc(p.ficheiro)}">${tEsc(p.nav)}</a></li>`).join('');
  const contactos = [k.telefone && `<li>${tIc('phone')}<a href="tel:${tEsc(String(k.telefone).replace(/\s+/g, ''))}">${tEsc(k.telefone)}</a></li>`,
    k.email && `<li>${tIc('mail')}<a href="mailto:${tEsc(k.email)}">${tEsc(k.email)}</a></li>`,
    k.morada && `<li>${tIc('map-pin')}<span>${tEsc(k.morada)}</span></li>`].filter(Boolean).join('');
  const horas = tLista(k.horario, 3).map(h => `<li>${tIc('clock')}<span>${tEsc(h.dias)}<br>${tEsc(h.horas)}</span></li>`).join('');
  const redes = `<div class="redes"><a href="${tEsc(tWa(c))}" aria-label="${tEsc(c.txt.whatsapp)}">${tIc('message-circle')}</a>${k.email ? `<a href="mailto:${tEsc(k.email)}" aria-label="${tEsc(c.txt.email)}">${tIc('mail')}</a>` : ''}${k.telefone ? `<a href="tel:${tEsc(String(k.telefone).replace(/\s+/g, ''))}" aria-label="${tEsc(c.txt.telefone)}">${tIc('phone')}</a>` : ''}</div>`;
  const base = `<div class="rod-base"><span>© ${ano} ${tEsc(d.marca.nome)}. ${tEsc(c.txt.direitos)}</span><span>${tEsc(d.marca.slogan || '')}</span></div>`;
  const marca = `<div><a class="marca" href="index.html" style="color:inherit">${c.logoUrl ? `<img src="${tEsc(c.logoUrl)}" alt="${tEsc(d.marca.nome)}">` : tEsc(d.marca.nome)}</a><p>${tEsc(d.marca.descricao || d.marca.slogan || '')}</p>${redes}</div>`;
  const colunas = `<div class="rod-grelha">${marca}<div><h4>${tEsc(c.txt.paginas)}</h4><ul>${links}</ul></div><div><h4>${tEsc(c.txt.contactos)}</h4><ul>${contactos}</ul></div><div><h4>${tEsc(c.txt.horario)}</h4><ul>${horas}</ul></div></div>`;
  if (v === 'minimal') return `<footer data-dia="rodape" class="rod"><div class="w"><div class="rod-min"><a class="marca" href="index.html" style="color:inherit">${tEsc(d.marca.nome)}</a><nav>${c.plano.filter(p => p.menu !== false).map(p => `<a href="${tEsc(p.ficheiro)}">${tEsc(p.nav)}</a>`).join('')}</nav>${redes}</div>${base}</div></footer>`;
  if (v === 'gigante') return `<footer data-dia="rodape" class="rod"><div class="w">${colunas}<div class="rod-gigante" aria-hidden="true">${tEsc(d.marca.nome)}</div>${base}</div></footer>`;
  if (v === 'cta') return `<footer data-dia="rodape" class="rod"><div class="w"><div class="rod-cta"><h3>${tEsc(d.cta.titulo || d.marca.slogan || '')}</h3><div class="btns">${tBtnP(d.cta.botao || d.hero.botao, c.ctaPrincipal)}${tBtnS(c.txt.whatsapp, tWa(c), 'message-circle')}</div></div>${colunas}${base}</div></footer>`;
  return `<footer data-dia="rodape" class="rod"><div class="w">${colunas}${base}</div></footer>`;
}

// Páginas do site de um template (com os nomes no idioma e do conteúdo).
function tPlano(t, conteudo, idioma) {
  const d = conteudo || {};
  const slugs = ['inicio'].concat((t.paginas || []).filter(s => s !== 'inicio' && PAGINAS_CATALOGO[s]));
  if (['loja'].some(s => slugs.includes(s)) && !slugs.includes('produto')) slugs.splice(slugs.indexOf('loja') + 1, 0, 'produto');
  if (!slugs.includes('contacto')) slugs.push('contacto');
  const sem = slugs.filter(s => s !== 'contacto').concat(['contacto']);
  return sem.map(s => {
    const b = paginaBase(s, idioma);
    const p = (d.paginas && d.paginas[s]) || {};
    return Object.assign(b, { nav: textoCurto(p.nav, 22) || b.nav, titulo: textoCurto(p.titulo, 70) || b.titulo, subtitulo: textoCurto(p.subtitulo, 160) || '' });
  });
}

// Secções da página inicial (o quiz entra antes da oferta)
function tSeccoesInicio(c) {
  const lista = (c.t.inicio || ['hero:dividido', 'servicos:cartoes', 'sobre:foto-lado', 'testemunhos:cartoes', 'faq:duas', 'cta:cartao']).slice();
  if (!lista.some(x => /^hero/.test(x))) lista.unshift('hero:' + (c.t.hero || 'dividido'));
  if (c.quiz) {
    const i = lista.findIndex(x => x === 'modulo:loja');
    lista.splice(i >= 0 ? i : 1, 0, 'quiz');
  }
  return lista;
}
function tMainModulo(c, p) {
  const ids = { loja: 'daniel-ia-produtos', produto: 'daniel-ia-produtos', portfolio: 'daniel-ia-portfolio', galeria: 'daniel-ia-galeria', blog: 'daniel-ia-blog' };
  const div = `<div id="${ids[p.modulo] || 'daniel-ia-produtos'}"></div>`;
  if (p.modulo === 'produto') return `<main data-dia="conteudo"><section class="s" style="padding-top:clamp(20px,3vw,36px)"><div class="w">${div}</div></section></main>`;
  return `<main data-dia="conteudo">${TPL_SECCOES.topo(c, (c.t.variantes && c.t.variantes.topo) === 'foto' ? 'simples' : ((c.t.variantes && c.t.variantes.topo) || 'simples'), { pagina: p.slug })}<section class="s s-modulo" style="padding-top:clamp(28px,4vw,48px)"><div class="w">${div}</div></section></main>`;
}

// Monta o site todo: a inicial completa (a "casca") e o <main> de cada página.
function montarTemplate({ t, conteudo, fotos, idioma, logoUrl, quiz, nome }) {
  const lingua = normalizarIdioma(idioma);
  const plano = tPlano(t, conteudo, lingua);
  const c = tContexto({ t, conteudo, fotos, idioma: lingua, logoUrl, plano, quiz, nome });
  const fontes = tFonteUrl([t.fontes && t.fontes.titulos, t.fontes && t.fontes.texto, t.tema && t.tema.destFonte]);
  const seo = c.d.seo || {};
  const tituloSite = textoCurto(seo.titulo, 70) || [c.d.marca.nome, c.d.marca.slogan].filter(Boolean).join(' · ');
  const descricao = textoCurto(seo.descricao || c.d.marca.descricao, 180);
  const cabeca = `<!DOCTYPE html>
<html lang="${lingua}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${tEsc(tituloSite)}</title>
<meta name="description" content="${tEsc(descricao)}">
<meta name="daniel-ia-template" content="${tEsc(t.id)}">
<script>document.documentElement.classList.add('js')</script>
${fontes ? `<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="${fontes}" rel="stylesheet">` : ''}
<style id="tpl-base">${tFichas(t)}${TPL_CSS}${t.css ? String(t.css).replace(/<\/?style[^>]*>/gi, '') : ''}</style>
</head>
<body>
`;
  const cab = tCabecalho(c);
  const rod = tRodape(c);
  const mainInicio = `<main data-dia="conteudo">${tMontarSeccoes(c, tSeccoesInicio(c), 'inicio')}</main>`;
  const casca = cabeca + cab + '\n' + mainInicio + '\n' + rod + `\n<script>${TPL_JS}</script>\n</body>\n</html>`;
  const fragmentos = {};
  plano.filter(p => p.slug !== 'inicio').forEach(p => {
    const main = p.modulo && p.modulo !== 'contacto'
      ? tMainModulo(c, p)
      : `<main data-dia="conteudo">${tMontarSeccoes(c, tReceitaPagina(p.slug, t), p.slug)}</main>`;
    fragmentos[p.slug] = { main, estilo: '', titulo: p.titulo, descricao: p.subtitulo || '' };
  });
  return { casca, fragmentos, plano, usos: [...c.usosPedidos] };
}

// ======================================================
// Catálogo dos templates
// ======================================================
let TEMPLATES = [];
try { TEMPLATES = TPL_CATALOGO; } catch (e) { TEMPLATES = []; }
const TEMPLATES_POR_ID = new Map(TEMPLATES.map(t => [t.id, t]));
function templatePublico(t) {
  return { id: t.id, tipo: t.tipo, nome: t.nome, sector: t.sector || '', resumo: t.resumo || '', cores: [t.tema && t.tema.primaria, t.tema && t.tema.fundo, t.tema && (t.tema.destaque || t.tema.escuro)].filter(Boolean), fontes: t.fontes || {}, paginas: tPlano(t, t.demo, 'pt').filter(p => p.menu !== false).map(p => p.nav), ficheiros: tPlano(t, t.demo, 'pt').filter(p => p.menu !== false).map(p => ({ nav: p.nav, ficheiro: p.ficheiro })) };
}

// ---- Fotos de demonstração (Pixabay, uma vez por template, guardadas no Bunny) ----
const cacheFotosDemo = new Map();
async function fotosDemoDoTemplate(t) {
  if (cacheFotosDemo.has(t.id)) return cacheFotosDemo.get(t.id);
  const caminho = `templates/${t.id}/fotos.json`;
  try {
    const guardado = JSON.parse((await descarregarDoBunny(caminho)).toString('utf8'));
    if (Array.isArray(guardado) && guardado.length) { cacheFotosDemo.set(t.id, guardado); return guardado; }
  } catch (e) {}
  const pedidos = tLista(t.demo && t.demo.fotos, 12);
  if (!pedidos.length || (!PIXABAY_API_KEY && !PEXELS_API_KEY)) return [];
  const usados = new Set(); const fotos = [];
  await emParalelo(pedidos, 4, async (p) => {
    try {
      const f = (await procurarFotoPexels(p.consulta, p.orientacao, usados).catch(() => null)) || (await procurarFotoPixabay(p.consulta, p.orientacao, usados));
      if (!f) return;
      const r = await fetch(f.url, { signal: AbortSignal.timeout(25000) });
      if (!r.ok) return;
      const url = await uploadParaBunny(`templates/${t.id}/${p.uso}.jpg`, Buffer.from(await r.arrayBuffer()), 'image/jpeg');
      fotos.push({ uso: p.uso, url });
    } catch (e) { console.error('Foto de demonstração ' + t.id + '/' + p.uso + ':', e.message || e); }
  });
  if (fotos.length) {
    await uploadParaBunny(caminho, Buffer.from(JSON.stringify(fotos), 'utf8'), 'application/json; charset=utf-8').catch(() => {});
    cacheFotosDemo.set(t.id, fotos);
  }
  return fotos;
}

// Página de pré-visualização de um template (conteúdo de demonstração).
const cachePreviaTpl = new Map();
async function previaDoTemplate(t, slug) {
  const chave = t.id + '/' + slug;
  const em = cachePreviaTpl.get(chave);
  if (em && Date.now() - em.t < 10 * 60 * 1000) return em.html;
  const fotos = await fotosDemoDoTemplate(t);
  const m = montarTemplate({ t, conteudo: t.demo, fotos, idioma: 'pt', quiz: false });
  const p = m.plano.find(x => x.slug === slug);
  let html = (!p || slug === 'inicio') ? m.casca : montarPagina(m.casca, p, m.fragmentos[slug], (t.demo && t.demo.marca && t.demo.marca.nome) || t.nome);
  html = definirMeta(html, 'daniel-ia-paginas', m.plano.filter(x => x.menu !== false).map(x => x.ficheiro).join(' '));
  html = definirMeta(html, 'daniel-ia-pagina', slug || 'inicio');
  if (t.tipo === 'E-commerce' || t.tipo === 'Checkout') html = marcarEstiloLoja(html, t.loja_cartao || 'suave', t.loja_tema || '');
  html = injectarLojaSeNecessario(html, t.tipo === 'E-commerce' || t.tipo === 'Checkout', 'previa');
  html = injectarGaleriaSeNecessario(html, t.tipo === 'Galeria', 'previa');
  html = injectarPortfolioSeNecessario(html, t.tipo === 'Portefólio', 'previa');
  html = injectarBlogSeNecessario(html, t.tipo === 'Blog', 'previa');
  html = injectarContactoSeNecessario(html, 'previa');
  // Links entre páginas da pré-visualização (com dia_previa para os módulos mostrarem exemplos)
  html = html.replace(/href="([a-z]+)\.html"/g, (x, s) => `href="${s}.html?dia_previa=1"`);
  cachePreviaTpl.set(chave, { t: Date.now(), html });
  return html;
}

// ======================================================
// A IA escreve o conteúdo do template para o negócio da pessoa
// ======================================================
const SISTEMA_TEMPLATE = 'És redactor publicitário sénior e estratega de marca de uma agência de topo. Escreves o conteúdo completo de um site profissional a partir de um template, para um negócio real. Respondes só com um objecto JSON válido.';
async function preencherTemplateIA({ t, nome, tipo, prompt, idioma, usos }) {
  const lingua = normalizarIdioma(idioma);
  const exemplo = Object.assign({}, t.demo || {}); delete exemplo.fotos;
  const pedido = [
    `Negócio: ${nome}. Tipo de site: ${tipo}. Template escolhido: "${t.nome}" (${t.sector || ''} - ${t.resumo || ''}).`,
    `Descrição do negócio, escrita pela pessoa: ${textoCurto(prompt, 2000)}`,
    `IDIOMA DO SITE: ${IDIOMAS_SITE[lingua].instrucao}`,
    'Abaixo está o conteúdo de EXEMPLO do template (de outro negócio). Devolve um JSON com EXACTAMENTE a mesma estrutura, os mesmos campos e o mesmo número de itens em cada lista, mas com TODO o conteúdo reescrito para ESTE negócio: concreto, rico, profissional e convincente, como o site de uma marca líder do sector. Nada do negócio de exemplo pode ficar (nomes, serviços, números, cidades).',
    'Regras: "marca.nome" é exactamente o nome do negócio. Preços em MZN (ex: "2 500 MZN") e só onde fizer sentido. Contactos: usa os da descrição; se não houver, usa "+258 84 000 0000", "info@" + um domínio simples do nome, e a cidade da descrição (ou Maputo). Números (anos, clientes...) realistas e modestos para um negócio deste tamanho - nunca exagerados. Depoimentos: exemplos realistas com só o primeiro nome e a cidade (o dono troca pelos verdadeiros). "destaque" do hero tem de ser uma palavra ou expressão curta que aparece tal e qual no "titulo". Campos "icone": só nomes desta lista: ' + NOMES_ICONES.join(', ') + '.',
    `Fotografias: devolve também "fotos": uma lista com estes usos exactos: ${usos.join(', ')}. Para cada uma: "uso", "consulta" (3 a 6 palavras em INGLÊS para procurar num banco de fotos, concretas e visuais, a condizer com este negócio; quando houver pessoas, prefere pessoas africanas; nunca marcas), "descricao" (em português, a foto ideal) e "orientacao" (paisagem, retrato ou quadrada).`,
    'EXEMPLO DO TEMPLATE:\n' + JSON.stringify(exemplo)
  ].join('\n\n');
  const res = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST', signal: AbortSignal.timeout(150000),
    headers: { Authorization: `Bearer ${OPENAI_API_KEY}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: OPENAI_MODEL, reasoning_effort: 'low', max_completion_tokens: 16000, response_format: { type: 'json_object' }, messages: [{ role: 'system', content: SISTEMA_TEMPLATE }, { role: 'user', content: pedido }] })
  });
  const json = await res.json();
  if (!res.ok) throw new Error('OpenAI falhou: ' + ((json.error && json.error.message) || res.status));
  const texto = String((json.choices && json.choices[0] && json.choices[0].message && json.choices[0].message.content) || '').trim();
  const m = texto.match(/\{[\s\S]*\}/);
  const dados = JSON.parse(m ? m[0] : texto);
  return { conteudo: dados, tokens: (json.usage && json.usage.total_tokens) || 0 };
}
// Junta o que a IA devolveu com a estrutura do exemplo (nada fica em falta).
function tFundirConteudo(exemplo, novo) {
  if (Array.isArray(exemplo)) return Array.isArray(novo) && novo.length ? novo.map((x, i) => tFundirConteudo(exemplo[i] !== undefined ? exemplo[i] : exemplo[0], x)) : exemplo;
  if (exemplo && typeof exemplo === 'object') {
    const r = {};
    Object.keys(exemplo).forEach(k => { r[k] = (novo && typeof novo === 'object' && k in novo) ? tFundirConteudo(exemplo[k], novo[k]) : exemplo[k]; });
    if (novo && typeof novo === 'object') Object.keys(novo).forEach(k => { if (!(k in r)) r[k] = novo[k]; });
    return r;
  }
  if (novo === undefined || novo === null || (typeof novo === 'string' && !novo.trim() && typeof exemplo === 'string' && exemplo)) return exemplo;
  return typeof novo === 'string' ? novo.slice(0, 1200) : novo;
}
function tPedidosFotos(t, usos, dados) {
  const daIA = tLista(dados && dados.fotos, 20);
  const demo = tLista(t.demo && t.demo.fotos, 20);
  return usos.slice(0, 12).map(u => {
    const f = daIA.find(x => x && x.uso === u) || demo.find(x => x && x.uso === u) || {};
    return { uso: u, consulta: textoCurto(f.consulta || (t.sector || 'business'), 100), descricao: textoCurto(f.descricao || f.consulta || '', 220), orientacao: ['paisagem', 'retrato', 'quadrada'].includes(f.orientacao) ? f.orientacao : 'paisagem' };
  });
}

// Criar um site a partir de um template (uma versão só, sem estúdio)
async function processarTemplate({ owner, nome, tipo, prompt, logo_data_url, siteId, generationId, mostrarMarcaDeAgua, idioma, quiz, t }) {
  try {
    let logoUrl = '';
    if (logo_data_url) {
      const match = /^data:(image\/[a-zA-Z0-9.+-]+);base64,(.+)$/.exec(logo_data_url);
      if (match) {
        const buffer = Buffer.from(match[2], 'base64');
        const espacoLogo = await verificarEspaco(owner, buffer.length);
        if (espacoLogo.ok) {
          const extensao = match[1].split('/')[1].replace('+xml', '').replace('jpeg', 'jpg');
          logoUrl = await uploadParaBunny(`logos/${owner}-${Date.now()}.${extensao}`, buffer, match[1]);
          await somarEspacoUsado(owner, buffer.length);
        }
      }
    }
    const slug = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    // Que fotos o template usa (montagem a seco com o conteúdo de exemplo)
    const usos = montarTemplate({ t, conteudo: t.demo, fotos: [], idioma, nome }).usos.filter(u => /^(capa|sobre|servico-\d|galeria-\d|equipa-\d)$/.test(u));
    const [iaR, quizR] = await Promise.all([
      preencherTemplateIA({ t, nome, tipo, prompt, idioma, usos }).catch(erro => { console.error('Conteúdo do template (IA) falhou - sigo com o exemplo:', erro.message || erro); return null; }),
      quiz ? gerarQuizIA({ nome, tipo, prompt, descricao: quiz.descricao, idioma }).then(r => guardarQuizNoSite(siteId, r.quiz).then(() => r)).catch(erro => { console.error('O quiz não foi criado:', erro.message || erro); return null; }) : Promise.resolve(null)
    ]);
    const conteudo = tFundirConteudo(t.demo || {}, iaR ? iaR.conteudo : {});
    delete conteudo.fotos;
    conteudo.marca = Object.assign({}, conteudo.marca, { nome });
    const fts = await prepararFotos({ owner, slug, pedidos: tPedidosFotos(t, usos, iaR && iaR.conteudo) });
    const m = montarTemplate({ t, conteudo, fotos: fts.fotos, idioma, logoUrl, quiz: !!quizR, nome });
    let html = prepararCasca(m.casca, m.plano);
    html = aplicarRedeResponsiva(html);
    const ehLoja = tipo === 'E-commerce' || tipo === 'Checkout';
    if (ehLoja) html = marcarEstiloLoja(html, t.loja_cartao || 'suave', t.loja_tema || '');
    html = injectarLojaSeNecessario(html, ehLoja, siteId);
    html = injectarQuizSeNecessario(html, ehLoja, siteId);
    html = injectarGaleriaSeNecessario(html, tipo === 'Galeria', siteId);
    html = injectarPortfolioSeNecessario(html, tipo === 'Portefólio', siteId);
    html = injectarBlogSeNecessario(html, tipo === 'Blog', siteId);
    html = injectarContactoSeNecessario(html, siteId);
    html = aplicarMarcaDeAgua(html, mostrarMarcaDeAgua);
    const caminhoSite = `sites/${owner}/${slug}/index.html`;
    const cdnUrl = await uploadParaBunny(caminhoSite, Buffer.from(html, 'utf8'), 'text/html; charset=utf-8');
    await uploadParaBunny(`sites/${owner}/${slug}/_paginas.json`, Buffer.from(JSON.stringify({ versao: 1, idioma: normalizarIdioma(idioma), fragmentos: m.fragmentos, template: t.id, actualizado: new Date().toISOString() }), 'utf8'), 'application/json; charset=utf-8');
    const tokens = (iaR ? iaR.tokens : 0) + (fts.tokens || 0) + (quizR ? quizR.tokens || 0 : 0);
    await bubblePatch('generation', generationId, { 'Status': 'Pronto', 'Tokens Usados': tokens });
    await cobrarTokensCriacao(owner, tokens);
    await bubblePatch('site', siteId, {
      'Status': 'Pronto', 'Bunny Path': caminhoSite, 'CDN URL': cdnUrl, 'Logo URL': logoUrl,
      'Variantes Json': JSON.stringify({ plano_paginas: m.plano, fotos: fts.fotos, template: { id: t.id, nome: t.nome }, paginas: { estado: 'a construir', lista: m.plano.filter(p => p.slug !== 'inicio').map(p => ({ slug: p.slug, estado: 'a construir' })) } })
    });
    await construirPaginas(siteId, { soMontar: true });
  } catch (erro) {
    console.error('Erro em processarTemplate:', erro);
    await bubblePatch('site', siteId, { 'Status': 'Erro' }).catch(() => {});
    await bubblePatch('generation', generationId, { 'Status': 'Erro' }).catch(() => {});
  }
}

// "Variar a partir deste template": as 3 versões da IA seguem o template.
function instrucaoTemplate(t, n) {
  const m = t.tema || {}, f = t.fontes || {};
  const nivel = ['FIEL: o mais parecido possível com o template - a mesma paleta, as mesmas letras, o mesmo cabeçalho e rodapé e a mesma sequência de secções.',
    'PARECIDA: a mesma paleta e as mesmas letras, mas com outra composição das secções e outro hero.',
    'INSPIRADA: parte do template (ambiente, cores e letras) e dá-lhe um toque novo e surpreendente.'][(n || 1) - 1] || '';
  return `\nTEMPLATE DE PARTIDA "${t.nome}" (${t.sector || ''}): ${t.resumo || ''}
Cores: fundo ${m.fundo || ''}, superfície ${m.superficie || ''}, texto ${m.texto || ''}, primária ${m.primaria || ''}, destaque ${m.destaque || ''}, escuro ${m.escuro || ''}. Letras: títulos "${f.titulos || ''}", texto "${f.texto || ''}". Cantos ${m.raio || ''}. Cabeçalho "${t.cabecalho || ''}", rodapé "${t.rodape || ''}".
Sequência de secções da inicial: ${(t.inicio || []).join(' → ')}.
NESTA VERSÃO: ${nivel}`;
}

// ---- Rotas ----
app.get('/templates', (req, res) => {
  const tipo = String(req.query.tipo || '');
  const lista = TEMPLATES.filter(t => !tipo || t.tipo === tipo).map(templatePublico);
  res.set('Cache-Control', 'public, max-age=300');
  res.json({ status: 'success', response: { templates: lista, total: lista.length } });
});
app.get('/template/:id/:ficheiro', async (req, res) => {
  try {
    const t = TEMPLATES_POR_ID.get(String(req.params.id || ''));
    const f = String(req.params.ficheiro || 'index.html');
    if (!t || !/^[a-z]+\.html$/.test(f)) return res.status(404).send('Template não encontrado.');
    const slug = f === 'index.html' ? 'inicio' : f.replace(/\.html$/, '');
    const html = await previaDoTemplate(t, slug);
    res.set('Content-Type', 'text/html; charset=utf-8');
    res.set('Cache-Control', 'public, max-age=600');
    res.removeHeader('X-Frame-Options');
    res.set('Content-Security-Policy', 'frame-ancestors *');
    res.send(html);
  } catch (erro) {
    console.error('Pré-visualização do template:', erro);
    res.status(500).send('Não foi possível mostrar este template.');
  }
});

function direcoesDoTemplate(t) {
  const est = baralhar(ESTRUTURAS_LAYOUT), her = baralhar(HEROS_LAYOUT);
  const tl = TEMAS_LOJA.find(x => x.id === t.loja_tema);
  return [['fiel', 'Fiel ao template'], ['parecida', 'Parecida'], ['inspirada', 'Inspirada']].map(([id, nm], i) => Object.assign({
    id: 'tpl-' + id, nome: nm + ' · ' + t.nome, resumo: t.resumo || '', prompt: instrucaoTemplate(t, i + 1),
    familia: 'claro', estrutura: est[i], hero: her[i], cartao: t.loja_cartao || ESTILOS_CARTAO_LOJA[i]
  }, tl ? { tema: tl.id, temaPrompt: tl.prompt } : {}));
}


// ======================================================
// Comprar domínios (1.60.0) - TurboHost (revendedor) + Bunny DNS
// ------------------------------------------------------
// 1. /dominio-procurar: disponibilidade + preço em MZN (TurboHost).
// 2. /dominio-pedido: guarda o pedido (tipo "dominio" no Bubble) e cria
//    uma Assinatura com Tipo "Dominio" - o pagamento usa as mesmas rotas
//    dos planos (/assinatura-pagar, /assinatura-estado, webhook).
// 3. Webhook pago -> Estado "Pago" -> o trabalhador (de 3 em 3 minutos):
//      Pago       : cria a zona no Bunny DNS e compra na TurboHost já com
//                   os nameservers do Bunny  -> "A registar"
//      A registar : pergunta o estado até "active"          -> "A ligar"
//      A ligar    : liga o site (Pull Zone + www) e o SSL    -> "Activo"
// 4. Renovação: aviso 30 e 7 dias antes, pagamento igual, renova na API.
// A chave da TurboHost só existe aqui (TURBOHOST_KEY) - nunca no browser.
// ======================================================
const TURBOHOST_KEY = clean(process.env.TURBOHOST_KEY);
const TURBOHOST_URL = (clean(process.env.TURBOHOST_URL) || 'https://my.turbo.host/api/reseller').replace(/\/+$/, '');
const DOMINIO_NS = ['kiki.bunny.net', 'coco.bunny.net'];
const DOMINIO_PADRAO = {
  taxa: Number(clean(process.env.DOMINIO_TAXA_USD)) || 66,
  margem: Number(clean(process.env.DOMINIO_MARGEM)) || 30,
  tlds: (clean(process.env.DOMINIO_TLDS) || 'co.mz,mz,com,net,org,store,shop,online,africa,co')
    .split(',').map(t => t.trim().toLowerCase().replace(/^\./, '')).filter(Boolean),
  fixos: {}
};
// Contacto técnico e de cobrança (opcional): JSON com FirstName, LastName,
// Company, EMail, City, State, AddressLine1, ZipCode, Phone. Sem ele, usa
// os dados do cliente em todos os contactos.
let DOMINIO_CONTACTO_TEC = null;
try { DOMINIO_CONTACTO_TEC = clean(process.env.DOMINIO_CONTACTO) ? JSON.parse(clean(process.env.DOMINIO_CONTACTO)) : null; } catch (e) { DOMINIO_CONTACTO_TEC = null; }

const ESTADOS_DOMINIO = ['Por pagar', 'Pago', 'A registar', 'A ligar', 'Activo', 'Erro', 'Expirado', 'Cancelado'];

async function turbo(caminho, corpo) {
  if (!TURBOHOST_KEY) throw new Error('A variável TURBOHOST_KEY não está configurada no container.');
  const r = await fetch(TURBOHOST_URL + caminho, {
    method: 'POST', signal: AbortSignal.timeout(45000),
    headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
    body: JSON.stringify(Object.assign({ key: TURBOHOST_KEY }, corpo))
  });
  const texto = await r.text();
  const json = lerJsonTurbo(texto);
  if (!r.ok || !json) {
    const e = new Error('TurboHost respondeu ' + r.status + ': ' + esconderChaveTurbo(texto).slice(0, 300));
    ultimoErroTurbo = { quando: new Date().toISOString(), rota: caminho, erro: e.message };
    throw e;
  }
  if (!turboOk(json)) ultimoErroTurbo = { quando: new Date().toISOString(), rota: caminho, erro: turboErro(json) };
  return json;
}
let ultimoErroTurbo = null;
// A TurboHost às vezes manda vários JSON colados ({...}{...}{...}): um por
// extensão que falhou e um com os resultados. Junta tudo num só objecto.
function lerJsonTurbo(texto) {
  texto = String(texto || '').trim();
  if (!texto) return null;
  try { return JSON.parse(texto); } catch (e) { /* pode vir colado */ }
  const partes = [];
  let nivel = 0, inicio = -1, emTexto = false, escape = false;
  for (let i = 0; i < texto.length; i++) {
    const ch = texto[i];
    if (emTexto) { if (escape) escape = false; else if (ch === '\\') escape = true; else if (ch === '"') emTexto = false; continue; }
    if (ch === '"') { emTexto = true; continue; }
    if (ch === '{') { if (nivel === 0) inicio = i; nivel++; }
    else if (ch === '}') { nivel--; if (nivel === 0 && inicio >= 0) { try { partes.push(JSON.parse(texto.slice(inicio, i + 1))); } catch (e) { /* ignora pedaço partido */ } inicio = -1; } }
  }
  if (!partes.length) return null;
  if (partes.length === 1) return partes[0];
  const boas = partes.filter(x => turboOk(x));
  const avisos = partes.filter(x => !turboOk(x)).map(x => turboErro(x));
  if (!boas.length) return Object.assign({}, partes[0], { avisos });
  const junto = Object.assign({}, boas[0], { avisos });
  boas.slice(1).forEach(x => {
    if (x.data && typeof x.data === 'object' && !Array.isArray(x.data) && junto.data && typeof junto.data === 'object' && !Array.isArray(junto.data)) Object.assign(junto.data, x.data);
    else if (Array.isArray(x.data) && Array.isArray(junto.data)) junto.data = junto.data.concat(x.data);
  });
  return junto;
}
// Disponibilidade de várias extensões. A TurboHost tira o ponto às extensões
// compostas (co.mz -> "comz") e diz que não existem; para essas tenta outras
// formas de perguntar e lembra-se da que funcionou.
const formaTldComposto = {};
function resultadoValido(x) {
  if (!x || typeof x !== 'object') return false;
  const st = String(x.status != null ? x.status : (x.available != null ? (x.available ? 'available' : 'unavailable') : '')).toLowerCase();
  return ['available', 'unavailable', 'registered', 'taken', 'free', 'true', 'false'].includes(st);
}
async function verDisponibilidade(sld, tlds) {
  const simples = tlds.filter(t => !t.includes('.'));
  const compostos = tlds.filter(t => t.includes('.'));
  const mapa = {};
  if (simples.length) {
    const j = await turbo('/domain-availability-check', { sld, tlds: simples });
    if (!turboOk(j)) throw new Error('Disponibilidade: ' + turboErro(j));
    Object.assign(mapa, mapaDisponibilidade(j));
  }
  await Promise.all(compostos.map(async t => {
    const dom = sld + '.' + t;
    const i = t.indexOf('.');
    const formas = [
      { nome: 'tld', corpo: { sld, tlds: [t] } },
      { nome: 'sld-com-ponto', corpo: { sld: sld + '.' + t.slice(0, i), tlds: [t.slice(i + 1)] } },
      { nome: 'tld-com-ponto', corpo: { sld, tlds: ['.' + t] } },
      { nome: 'dominio', corpo: { domain: dom, sld, tld: t } }
    ];
    const primeiro = formaTldComposto[t];
    if (primeiro) formas.sort((a, b) => (a.nome === primeiro ? -1 : 0) - (b.nome === primeiro ? -1 : 0));
    for (const f of formas) {
      try {
        const j = await turbo('/domain-availability-check', f.corpo);
        const m = mapaDisponibilidade(j);
        // Só vale a resposta para ESTE domínio exacto. A TurboHost pode "limpar" o nome
        // (ex: djdesign.com + br -> djdesigncom.br) e responder sobre outro domínio.
        const x = m[dom];
        if (resultadoValido(x)) { mapa[dom] = x; formaTldComposto[t] = f.nome; return; }
      } catch (e) { /* tenta a forma seguinte */ }
    }
    mapa[dom] = { status: 'unknown' };
  }));
  return mapa;
}
function esconderChaveTurbo(t) {
  t = String(t || '');
  return TURBOHOST_KEY ? t.split(TURBOHOST_KEY).join('***') : t;
}
function turboOk(json) {
  if (!json) return false;
  const st = String(json.status || json.result || '').toLowerCase();
  if (['successful', 'success', 'ok', 'true'].includes(st)) return true;
  // algumas respostas não trazem "status", só os dados
  return !json.status && !json.error && !json.errors && (json.data != null || json.id != null || json.invoice_id != null);
}
// Lista de produtos, venha como lista, como objecto ou dentro de data.domains
function listaTurbo(d) {
  if (Array.isArray(d)) return d;
  if (d && typeof d === 'object') {
    for (const k of ['domains', 'products', 'items', 'list']) if (Array.isArray(d[k])) return d[k];
    return Object.keys(d).map(k => (d[k] && typeof d[k] === 'object') ? Object.assign({ name: d[k].name || k }, d[k]) : null).filter(Boolean);
  }
  return [];
}
// Resposta da disponibilidade -> { "nome.tld": {status, premium} }
function mapaDisponibilidade(j) {
  const d = j && (j.data != null ? j.data : j);
  const m = {};
  const juntar = (x, chave) => {
    if (!x || typeof x !== 'object') return;
    const dom = String(x.domain || x.domain_name || (x.sld && x.tld ? x.sld + '.' + String(x.tld).replace(/^\./, '') : '') || chave || '').toLowerCase();
    if (dom) m[dom] = x;
  };
  if (Array.isArray(d)) d.forEach(x => juntar(x));
  else if (d && typeof d === 'object') Object.keys(d).forEach(k => juntar(d[k], k));
  return m;
}
function livreTurbo(x) {
  if (!x) return false;
  const st = String(x.status != null ? x.status : (x.available != null ? (x.available ? 'available' : 'unavailable') : '')).toLowerCase();
  return st === 'available' || st === 'free' || st === 'true';
}
function turboErro(json) {
  if (!json) return 'sem resposta';
  return String(json.message || json.error || json.msg || (json.errors && JSON.stringify(json.errors)) || json.status || 'erro desconhecido').slice(0, 300);
}

// ---- Configuração (taxa, margem, extensões e preços fixos), editável no painel ----
let cacheConfigDominios = null;
async function configDominios() {
  if (cacheConfigDominios && Date.now() - cacheConfigDominios.t < 60000) return cacheConfigDominios.c;
  let c = Object.assign({}, DOMINIO_PADRAO);
  try {
    const guardado = JSON.parse((await descarregarDoBunny('config/dominios.json')).toString('utf8'));
    if (guardado && typeof guardado === 'object') {
      if (Number(guardado.taxa) > 0) c.taxa = Number(guardado.taxa);
      if (Number(guardado.margem) >= 0) c.margem = Number(guardado.margem);
      if (Array.isArray(guardado.tlds) && guardado.tlds.length) c.tlds = guardado.tlds;
      if (guardado.fixos && typeof guardado.fixos === 'object') c.fixos = guardado.fixos;
    }
  } catch (e) { /* ainda não há configuração guardada */ }
  cacheConfigDominios = { t: Date.now(), c };
  return c;
}
function limparTld(t) { return String(t || '').trim().toLowerCase().replace(/^\.+/, '').replace(/[^a-z0-9.]/g, '').slice(0, 24); }

// ---- Preços da TurboHost (cache de 6 horas) ----
let cacheProdutosDominio = null;
async function produtosDominio(forcar) {
  if (!forcar && cacheProdutosDominio && Date.now() - cacheProdutosDominio.t < 6 * 3600 * 1000) return cacheProdutosDominio.m;
  const j = await turbo('/products', { types: ['domain'] });
  const lista = listaTurbo(j && j.data != null ? j.data : j);
  if (!turboOk(j) || !lista.length) throw new Error('Preços da TurboHost: ' + turboErro(j));
  const m = new Map();
  lista.forEach(p => {
    const nome = p && String(p.name || p.tld || p.extension || '').toLowerCase().replace(/^\./, '');
    if (nome && (!p.type || p.type === 'domain')) m.set(nome, p);
  });
  if (!m.size) throw new Error('Preços da TurboHost: a lista veio sem extensões.');
  cacheProdutosDominio = { t: Date.now(), m };
  return m;
}
// Custo na TurboHost, sempre em meticais (sem promoções: nunca vendemos
// abaixo do custo). A conta da TurboHost pode cobrar em MZN (o caso real)
// ou em USD; só em USD é que se usa o câmbio.
function moedaDe(p, tipo) {
  const x = p && p.pricing && p.pricing[tipo || 'register'];
  return String((x && x.currency) || 'USD').toUpperCase();
}
function custoMznDe(p, tipo, c) {
  const x = p && p.pricing && p.pricing[tipo];
  if (!x || x.period === 'none') return 0;
  const valor = Math.max(0, Number(x.amount) || 0);
  return moedaDe(p, tipo) === 'MZN' ? valor : valor * c.taxa;
}
function mznDe(custoMzn, c) {
  if (!(custoMzn > 0)) return 0;
  return Math.ceil((custoMzn * (1 + c.margem / 100)) / 10) * 10;
}
function precosDoTld(tld, p, c) {
  const fixo = c.fixos && Number(c.fixos[tld]) > 0 ? Math.round(Number(c.fixos[tld])) : 0;
  const custo = {
    registo: custoMznDe(p, 'register', c), renovacao: custoMznDe(p, 'renewal', c),
    transferencia: custoMznDe(p, 'transfer', c), privacidade: custoMznDe(p, 'whois_privacy', c)
  };
  return {
    registo: fixo || mznDe(custo.registo, c),
    renovacao: fixo || mznDe(custo.renovacao, c),
    transferencia: mznDe(custo.transferencia, c),
    privacidade: mznDe(custo.privacidade, c),
    moeda: moedaDe(p),
    custo_mzn: custo
  };
}
// Campos extra que a extensão exige (ex: número de identificação, um ficheiro).
function documentosDoTld(p) {
  const lista = [];
  (Array.isArray(p && p.documents) ? p.documents : []).forEach(grupo => {
    if (!grupo || typeof grupo !== 'object') return;
    Object.keys(grupo).forEach(chave => {
      const d = grupo[chave] || {};
      if (!/^[A-Za-z0-9_]{1,40}$/.test(chave)) return;
      lista.push({
        chave, nome: textoCurto(d.name || chave, 80), tipo: ['text', 'select', 'file'].includes(d.type) ? d.type : 'text',
        descricao: textoCurto(d.description || '', 240), obrigatorio: d.required !== false,
        opcoes: d.options && typeof d.options === 'object' ? Object.keys(d.options).slice(0, 40).map(k => ({ valor: k, texto: textoCurto(d.options[k], 80) })) : [],
        extensoes: textoCurto(d.allowed_ext || '', 80), max_mb: Number(d.max_file_size) || 3
      });
    });
  });
  return lista;
}

// "Padaria Sol" -> "padariasol"; "padariasol.co.mz" -> { sld: "padariasol", tld: "co.mz" }
function separarDominio(texto, tldsConhecidos) {
  let v = limparDominio(texto).replace(/^www\./, '').replace(/\s+/g, '');
  v = v.normalize('NFD').replace(/[̀-ͯ]/g, '');
  const tlds = tldsConhecidos.slice().sort((a, b) => b.length - a.length);
  let tld = '';
  for (const t of tlds) { if (v.endsWith('.' + t)) { tld = t; v = v.slice(0, -t.length - 1); break; } }
  if (!tld && v.includes('.')) { const i = v.indexOf('.'); tld = limparTld(v.slice(i + 1)); v = v.slice(0, i); }
  const sld = v.replace(/[^a-z0-9-]/g, '').replace(/^-+|-+$/g, '').slice(0, 63);
  return { sld, tld };
}

// ---- Pesquisa: disponibilidade + preço ----
app.post('/dominio-procurar', async (req, res) => {
  try {
    if (!TURBOHOST_KEY) return res.json({ status: 'error', message: 'A compra de domínios ainda não está activa. Tenta mais tarde.' });
    const c = await configDominios();
    const produtos = await produtosDominio();
    const { sld, tld } = separarDominio(req.body.nome, Array.from(produtos.keys()));
    if (sld.length < 2) return res.json({ status: 'error', message: 'Escreve o nome que queres (pelo menos 2 letras ou números).' });
    let tlds = c.tlds.filter(t => produtos.has(t));
    if (tld) {
      if (!produtos.has(tld)) return res.json({ status: 'error', message: 'Ainda não vendemos domínios ".' + tld + '". Experimenta outra extensão.' });
      tlds = [tld].concat(tlds.filter(t => t !== tld));
    }
    tlds = tlds.slice(0, 14);
    const disp = await verDisponibilidade(sld, tlds);
    const lista = tlds.map(t => {
      const d = disp[sld + '.' + t] || {};
      const p = produtos.get(t);
      const pr = precosDoTld(t, p, c);
      const livre = livreTurbo(d);
      return {
        dominio: sld + '.' + t, tld: t, livre: livre && !d.premium, premium: !!d.premium,
        estado: d.premium ? 'premium' : (livre ? 'livre' : (resultadoValido(d) ? 'ocupado' : 'desconhecido')),
        preco: pr.registo, renovacao: pr.renovacao, transferencia: pr.transferencia, privacidade: pr.privacidade,
        documentos: documentosDoTld(p)
      };
    }).filter(x => x.preco > 0);
    return res.json({ status: 'success', response: { sld, procurado: tld ? sld + '.' + tld : '', resultados: lista } });
  } catch (erro) {
    console.error('Erro em /dominio-procurar:', esconderChaveTurbo(erro.message || erro));
    return res.json({ status: 'error', message: 'Não foi possível procurar agora. Tenta outra vez daqui a pouco.' });
  }
});

// ---- Pedido: guarda os dados e cria o pagamento ----
function limparContacto(t, email) {
  const s = (v, n) => textoCurto(v, n || 80);
  const tel = String((t && t.telefone) || '').replace(/\D/g, '').replace(/^258/, '').slice(0, 12);
  const nomeCompleto = s(t && t.nome, 120);
  const partes = nomeCompleto.split(/\s+/);
  return {
    FirstName: s(t && t.primeiro_nome) || partes[0] || '',
    LastName: s(t && t.apelido) || partes.slice(1).join(' ') || partes[0] || '',
    Company: s(t && t.empresa, 100),
    EMail: s(t && t.email, 120) || email || '',
    Country: (s(t && t.pais, 2) || 'MZ').toUpperCase(),
    City: s(t && t.cidade, 60),
    State: s(t && t.provincia, 60) || s(t && t.cidade, 60),
    AddressLine1: s(t && t.morada, 120),
    AddressLine2: '',
    ZipCode: s(t && t.codigo_postal, 12) || '1100',
    PhoneCountryCode: Number(String((t && t.indicativo) || '258').replace(/\D/g, '')) || 258,
    Phone: tel,
    FaxCountryCode: Number(String((t && t.indicativo) || '258').replace(/\D/g, '')) || 258,
    Fax: tel
  };
}
function contactoValido(c) {
  if (!c.FirstName || !c.LastName) return 'Escreve o nome completo do titular.';
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(c.EMail)) return 'Escreve um email válido do titular.';
  if (c.Phone.length < 8) return 'Escreve um número de telefone válido do titular.';
  if (!c.City) return 'Escreve a cidade do titular.';
  if (!c.AddressLine1 || c.AddressLine1.length < 4) return 'Escreve a morada do titular.';
  return '';
}
async function lerSensivelDominio(id) {
  try { return JSON.parse(decifrarKyc(await descarregarDoBunny(`dominios-privado/${id}.bin`)).toString('utf8')); } catch (e) { return {}; }
}
async function guardarSensivelDominio(id, dados) {
  await uploadParaBunny(`dominios-privado/${id}.bin`, cifrarKyc(Buffer.from(JSON.stringify(dados), 'utf8')), 'application/octet-stream');
}
function dadosDominio(d) { return lerJsonSeguro(d && d['Dados Json'], {}) || {}; }
async function mudarDominio(id, estado, mudar) {
  const d = await bubbleGet('dominio', id);
  const dados = dadosDominio(d);
  if (typeof mudar === 'function') mudar(dados, d);
  dados.historico = (dados.historico || []).concat([{ em: new Date().toISOString(), estado: estado || d['Estado'], nota: dados.ultima_nota || '' }]).slice(-30);
  delete dados.ultima_nota;
  const patch = { 'Dados Json': JSON.stringify(dados) };
  if (estado) patch['Estado'] = estado;
  if (dados.expira) patch['Expira'] = dados.expira;
  await bubblePatch('dominio', id, patch);
  return Object.assign({}, d, patch, { _id: id });
}

app.post('/dominio-pedido', async (req, res) => {
  try {
    const { owner, site_id } = req.body;
    if (!TURBOHOST_KEY) return res.json({ status: 'error', message: 'A compra de domínios ainda não está activa. Tenta mais tarde.' });
    const validacao = await validarSiteParaDominio(owner, site_id);
    if (validacao.erro) return res.json({ status: 'error', codigo: /plano/i.test(validacao.erro) ? 'plano' : '', message: validacao.erro });
    const c = await configDominios();
    const produtos = await produtosDominio();
    const { sld, tld } = separarDominio(req.body.dominio, Array.from(produtos.keys()));
    const p = produtos.get(tld);
    if (!sld || !p) return res.json({ status: 'error', message: 'Escolhe um domínio da lista.' });
    const dominio = sld + '.' + tld;
    const transferir = req.body.operacao === 'transferencia';
    const epp = textoCurto(req.body.epp, 120);
    if (transferir && !epp) return res.json({ status: 'error', message: 'Para transferir, escreve o código de transferência (EPP/Auth Code) que o teu registador actual te deu.' });
    const user = await bubbleGet('user', owner);
    const titular = limparContacto(req.body.titular || {}, emailDoUsuario(user));
    const erroTitular = contactoValido(titular);
    if (erroTitular) return res.json({ status: 'error', message: erroTitular });
    // Documentos pedidos pela extensão
    const pedidos = documentosDoTld(p);
    const docs = {};
    const recebidos = (req.body.documentos && typeof req.body.documentos === 'object') ? req.body.documentos : {};
    for (const d of pedidos) {
      const v = recebidos[d.chave];
      if (d.tipo === 'file') {
        const m = v && /^data:([a-z0-9.+\/-]+);base64,([A-Za-z0-9+/=]+)$/i.exec(String(v.data || ''));
        if (!m) { if (d.obrigatorio) return res.json({ status: 'error', message: 'Falta o ficheiro "' + d.nome + '".' }); continue; }
        if (m[2].length * 0.75 > d.max_mb * 1048576) return res.json({ status: 'error', message: 'O ficheiro "' + d.nome + '" é demasiado grande (máximo ' + d.max_mb + ' MB).' });
        docs[d.chave] = { name: textoCurto(v.nome || 'documento', 80).replace(/[^\w.\- ]/g, ''), data: m[2] };
      } else {
        const t = textoCurto(v, 200);
        if (!t && d.obrigatorio) return res.json({ status: 'error', message: 'Preenche o campo "' + d.nome + '".' });
        if (d.tipo === 'select' && t && !d.opcoes.some(o => o.valor === t)) return res.json({ status: 'error', message: 'Escolhe uma opção válida em "' + d.nome + '".' });
        if (t) docs[d.chave] = t;
      }
    }
    // Ainda está livre? (para transferências tem de estar ocupado)
    if (!transferir) {
      const d = (await verDisponibilidade(sld, [tld]))[dominio];
      if (!d || !livreTurbo(d) || d.premium) {
        return res.json({ status: 'error', message: 'Alguém registou "' + dominio + '" agora mesmo, ou não está disponível. Escolhe outro.' });
      }
    }
    const pr = precosDoTld(tld, p, c);
    const privacidade = req.body.privacidade === true && pr.privacidade > 0;
    const base = transferir ? pr.transferencia : pr.registo;
    if (!(base > 0)) return res.json({ status: 'error', message: 'Esta extensão não está à venda neste momento.' });
    const valor = base + (privacidade ? pr.privacidade : 0);
    const custoMzn = (transferir ? pr.custo_mzn.transferencia : pr.custo_mzn.registo) + (privacidade ? pr.custo_mzn.privacidade : 0);
    const dominioId = await bubbleCreate('dominio', {
      'Owner': owner, 'Site': site_id, 'Nome': dominio, 'Estado': 'Por pagar', 'Valor MZN': valor,
      'Dados Json': JSON.stringify({
        tld, sld, operacao: transferir ? 'transferencia' : 'registo', anos: 1, privacidade, custo_mzn: Math.round(custoMzn * 100) / 100, moeda_turbo: pr.moeda,
        taxa: c.taxa, margem: c.margem, titular: { nome: titular.FirstName + ' ' + titular.LastName, email: titular.EMail, cidade: titular.City },
        criado: new Date().toISOString(), tentativas: 0, historico: [{ em: new Date().toISOString(), estado: 'Por pagar' }]
      })
    });
    await guardarSensivelDominio(dominioId, { titular, docs, epp: transferir ? epp : '' });
    const assinaturaId = await bubbleCreate('assinatura', {
      'User': owner, 'Valor MZN': valor, 'Metodo': '', 'ID Pagamento': '', 'Estado': 'Pendente', 'Transaction ID': '',
      'Webhook Processado': false, 'Tipo': 'Dominio', 'Pacote': dominioId, 'Created Date': new Date().toISOString()
    });
    await mudarDominio(dominioId, null, dd => { dd.assinatura = assinaturaId; });
    return res.json({ status: 'success', response: { dominio_id: dominioId, assinatura_id: assinaturaId, dominio, valor_mzn: valor } });
  } catch (erro) {
    console.error('Erro em /dominio-pedido:', erro.message || erro);
    return res.json({ status: 'error', message: 'Não foi possível preparar a compra. Tenta outra vez.' });
  }
});

