    await uploadParaBunny('config/dominios.json', Buffer.from(JSON.stringify(c), 'utf8'), 'application/json; charset=utf-8');
    cacheConfigDominios = { t: Date.now(), c: Object.assign({}, DOMINIO_PADRAO, c) };
