// ======================================================
// Estatísticas dos sites (1.62.0)
// ------------------------------------------------------
// 1. Cada página dos sites leva /dia-medir.js (posto sozinho quando o HTML
//    é gravado no Bunny - ver comMedicao, chamada pelo uploadParaBunny).
//    O script manda um "beacon" anónimo a /m: página vista, de onde veio,
//    telemóvel ou computador, produto visto, clique no WhatsApp/telefone.
//    Sem cookies nem dados pessoais: o visitante é só um número ao acaso
//    guardado no navegador, para contar visitantes únicos por dia.
// 2. O servidor soma tudo em memória e grava de minuto a minuto em
//    estatisticas/<owner>/<slug>/<AAAA-MM>.json (um ficheiro por mês).
// 3. /estatisticas junta as visitas com as encomendas da loja e devolve
//    tudo pronto para os gráficos do painel.
// ======================================================
const EST_DIAS_PERMITIDOS = [7, 30, 90];

const MEDIR_JS = `(function(){
  try {
    var s = document.currentScript;
    var k = s && s.getAttribute('data-k');
    if (!k) return;
    var ficheiro = (location.pathname.split('/').pop() || 'index.html');
    if (/^v\\d+\\.html$/.test(ficheiro) || /dia_previa/.test(location.search)) return;
    if (/bot|crawl|spider|headless|lighthouse/i.test(navigator.userAgent || '')) return;
    var U = ${JSON.stringify(SELF_URL + '/m')};
    var vid = '';
    try {
      vid = localStorage.getItem('dia_v') || '';
      if (!/^[a-z0-9]{8,40}$/.test(vid)) { vid = (Math.random().toString(36).slice(2) + Date.now().toString(36)).slice(0, 24); localStorage.setItem('dia_v', vid); }
    } catch (e) { vid = ''; }
    var rh = '';
    try { rh = document.referrer ? new URL(document.referrer).hostname : ''; } catch (e) { rh = ''; }
    if (rh && rh === location.hostname) rh = '=';
    var q = location.search || '';
    var utm = (/[?&]utm_source=([^&]{1,40})/.exec(q) || [])[1] || (/[?&]fbclid=/.test(q) ? 'facebook' : '') || (/[?&]gclid=/.test(q) ? 'google' : '');
    function env(t, x){
      var corpo = JSON.stringify({ k: k, t: t, x: x || '', v: vid, p: ficheiro, r: rh, u: utm, d: (window.innerWidth || 1000) < 768 ? 'm' : 'd' });
      try {
        if (navigator.sendBeacon && navigator.sendBeacon(U, new Blob([corpo], { type: 'text/plain' }))) return;
      } catch (e) {}
      try { fetch(U, { method: 'POST', body: corpo, keepalive: true, mode: 'no-cors', headers: { 'Content-Type': 'text/plain' } }); } catch (e) {}
    }
    env('v');
    window.addEventListener('dia-produto-visto', function(e){ if (e && e.detail) env('p', String(e.detail)); });
    document.addEventListener('click', function(e){
      var a = e.target && e.target.closest ? e.target.closest('a') : null;
      if (!a) return;
      var h = (a.getAttribute('href') || '').toLowerCase();
      if (/wa\\.me|whatsapp\\.com|whatsapp:/.test(h)) env('w');
      else if (h.indexOf('tel:') === 0) env('c', 'tel');
      else if (h.indexOf('mailto:') === 0) env('c', 'mail');
    }, true);
    var abrir = window.open;
    window.open = function(u){
      try { if (/wa\\.me|whatsapp/i.test(String(u || ''))) env('w'); } catch (e) {}
      return abrir.apply(window, arguments);
    };
  } catch (e) {}
})();`;

app.get('/dia-medir.js', (req, res) => {
  res.set('Content-Type', 'application/javascript; charset=utf-8');
  res.set('Cache-Control', 'public, max-age=3600');
  res.send(MEDIR_JS);
});

// ---- Pôr o script nas páginas dos sites (chamado pelo uploadParaBunny) ----
const RE_CAMINHO_SITE = /^sites\/([A-Za-z0-9_-]{1,64})\/([A-Za-z0-9_.-]{1,80})\/([A-Za-z0-9_.-]{1,80}\.html)$/;
function injectarMedicao(html, k) {
  if (/dia-medir\.js/.test(html)) return html;
  const tag = `<script src="${SELF_URL}/dia-medir.js" data-k="${k}" defer></script>`;
  return /<\/body>/i.test(html) ? html.replace(/<\/body>(?![\s\S]*<\/body>)/i, tag + '\n</body>') : html + '\n' + tag;
}
function comMedicao(caminho, buffer, contentType) {
  try {
    if (!/text\/html/i.test(String(contentType || ''))) return buffer;
    const m = RE_CAMINHO_SITE.exec(String(caminho || '').replace(/^\/+/, ''));
    if (!m || /^v\d+\.html$/.test(m[3])) return buffer;
    const ehBuffer = Buffer.isBuffer(buffer);
    const html = ehBuffer ? buffer.toString('utf8') : String(buffer);
    if (/dia-medir\.js/.test(html)) return buffer;
    const novo = injectarMedicao(html, m[1] + '/' + m[2]);
    return ehBuffer ? Buffer.from(novo, 'utf8') : novo;
  } catch (e) {
    return buffer;
  }
}
// 'sites/<owner>/<slug>/index.html' -> 'owner/slug'
function chaveMedicaoDoSite(site) {
  const m = /^\/?sites\/([A-Za-z0-9_-]{1,64})\/([A-Za-z0-9_.-]{1,80})\//.exec(String(site['Bunny Path'] || ''));
  return m ? m[1] + '/' + m[2] : '';
}

// ---- Dia em Maputo (UTC+2, sem hora de Verão) ----
function diaMaputo(t) { return new Date((t || Date.now()) + 2 * 3600 * 1000).toISOString().slice(0, 10); }
function somarDias(dia, n) { const d = new Date(dia + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); }

// ---- De onde veio a visita ----
function origemDaVisita(r, utm) {
  const u = String(utm || '').toLowerCase();
  const h = String(r || '').toLowerCase();
  const teste = (x) => {
    if (!x) return '';
    if (/google|gclid/.test(x)) return 'Google';
    if (/facebook|fb\.|fbclid|^fb$|messenger/.test(x)) return 'Facebook';
    if (/instagram|^ig$/.test(x)) return 'Instagram';
    if (/whatsapp|wa\.me|^wa$/.test(x)) return 'WhatsApp';
    if (/tiktok/.test(x)) return 'TikTok';
    if (/linkedin|lnkd/.test(x)) return 'LinkedIn';
    if (/youtube|youtu\.be/.test(x)) return 'YouTube';
    if (/^t\.co$|twitter|^x\.com$/.test(x)) return 'X (Twitter)';
    if (/bing|yahoo|duckduckgo|ecosia|yandex|baidu/.test(x)) return 'Outras pesquisas';
    return '';
  };
  return teste(u) || teste(h) || (u ? 'Outros sites' : (h ? 'Outros sites' : 'Directo'));
}

// ---- Documentos de um mês (em memória, gravados de minuto a minuto) ----
const estDocs = new Map(); // `${k}|${mes}` -> { doc, sujo, usado, ids: Map(dia -> Set), pronto: Promise }
function caminhoEst(k, mes) { return 'estatisticas/' + k + '/' + mes + '.json'; }
function entradaEst(k, mes) {
  const chave = k + '|' + mes;
  let e = estDocs.get(chave);
  if (!e) {
    e = { k, mes, doc: { dias: {} }, sujo: false, usado: Date.now(), ids: new Map() };
    e.pronto = descarregarDoBunny(caminhoEst(k, mes))
      .then(b => {
        const d = JSON.parse(b.toString('utf8'));
        if (d && typeof d === 'object' && d.dias) {
          // junta o que chegou enquanto se lia o ficheiro
          const extra = e.doc;
          e.doc = d;
          if (d.ids_dia && Array.isArray(d.ids_dia.ids)) e.ids.set(d.ids_dia.dia, new Set(d.ids_dia.ids));
          Object.keys(extra.dias).forEach(dia => somarDia(e.doc, dia, extra.dias[dia]));
        }
      })
      .catch(() => {});
    estDocs.set(chave, e);
  }
  e.usado = Date.now();
  return e;
}
function diaVazio() { return { v: 0, u: 0, o: {}, d: {}, p: {}, pr: {}, w: 0, c: 0, ct: {} }; }
function somarDia(doc, dia, x) {
  const a = doc.dias[dia] || (doc.dias[dia] = diaVazio());
  ['v', 'u', 'w', 'c'].forEach(k => { a[k] = (a[k] || 0) + (x[k] || 0); });
  ['o', 'd', 'p', 'pr', 'ct'].forEach(k => {
    a[k] = a[k] || {};
    Object.keys(x[k] || {}).forEach(n => { a[k][n] = (a[k][n] || 0) + x[k][n]; });
  });
}
function mais(obj, chave, n) {
  if (Object.keys(obj).length >= 400 && !(chave in obj)) chave = 'outros';
  obj[chave] = (obj[chave] || 0) + (n || 1);
}
async function registarMedicao(k, evento) {
  const dia = diaMaputo();
  const e = entradaEst(k, dia.slice(0, 7));
  await e.pronto;
  const a = e.doc.dias[dia] || (e.doc.dias[dia] = diaVazio());
  if (evento.t === 'v') {
    a.v++;
    mais(a.p, evento.p || 'index.html');
    mais(a.d, evento.d === 'm' ? 'm' : 'd');
    if (evento.r !== '=') mais(a.o, origemDaVisita(evento.r, evento.u));
    if (evento.v) {
      let s = e.ids.get(dia);
      if (!s) { s = new Set(); e.ids.set(dia, s); }
      if (!s.has(evento.v) && s.size < 20000) { s.add(evento.v); a.u++; }
    } else {
      a.u++;
    }
  } else if (evento.t === 'p' && evento.x) {
    mais(a.pr, evento.x);
  } else if (evento.t === 'w') {
    a.w++;
  } else if (evento.t === 'c') {
    a.c++;
    mais(a.ct, ['tel', 'mail', 'form'].includes(evento.x) ? evento.x : 'outro');
  }
  e.sujo = true;
}
async function gravarEstatisticas() {
  const hoje = diaMaputo();
  for (const [chave, e] of estDocs) {
    if (e.sujo) {
      e.sujo = false;
      const s = e.ids.get(hoje);
      e.doc.ids_dia = s ? { dia: hoje, ids: Array.from(s).slice(0, 20000) } : undefined;
      try {
        await uploadParaBunny(caminhoEst(e.k, e.mes), Buffer.from(JSON.stringify(e.doc), 'utf8'), 'application/json; charset=utf-8');
      } catch (erro) {
        e.sujo = true;
        console.error('Estatísticas: não gravou', chave, erro.message || erro);
      }
    } else if (Date.now() - e.usado > 2 * 3600 * 1000) {
      estDocs.delete(chave);
    }
    for (const dia of e.ids.keys()) if (dia !== hoje) e.ids.delete(dia);
  }
}
setInterval(() => { gravarEstatisticas().catch(() => {}); }, 60 * 1000).unref();
let estAFechar = false;
['SIGTERM', 'SIGINT'].forEach(sinal => process.on(sinal, () => {
  if (estAFechar) return;
  estAFechar = true;
  const fim = setTimeout(() => process.exit(0), 5000);
  gravarEstatisticas().catch(() => {}).finally(() => { clearTimeout(fim); process.exit(0); });
}));

// ---- Recolha: o beacon dos sites ----
const RE_K = /^[A-Za-z0-9_-]{1,64}\/[A-Za-z0-9_.-]{1,80}$/;
app.post('/m', express.text({ type: () => true, limit: '4kb' }), (req, res) => {
  res.status(204).end();
  try {
    let b = req.body;
    if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { return; } }
    if (!b || typeof b !== 'object') return;
    const k = String(b.k || '');
    if (!RE_K.test(k)) return;
    if (/bot|crawl|spider|headless|lighthouse|preview|facebookexternalhit|whatsapp\//i.test(String(req.headers['user-agent'] || ''))) return;
    const t = String(b.t || '');
    if (!['v', 'p', 'w', 'c'].includes(t)) return;
    const p = /^[A-Za-z0-9_.-]{1,60}\.html$/.test(String(b.p || '')) ? String(b.p) : 'index.html';
    if (/^v\d+\.html$/.test(p)) return;
    const evento = {
      t, p,
      x: /^[A-Za-z0-9_-]{1,40}$/.test(String(b.x || '')) ? String(b.x) : '',
      v: /^[a-z0-9]{8,40}$/.test(String(b.v || '')) ? String(b.v) : '',
      r: b.r === '=' ? '=' : String(b.r || '').toLowerCase().replace(/[^a-z0-9.-]/g, '').slice(0, 80),
      u: String(b.u || '').toLowerCase().replace(/[^a-z0-9._-]/g, '').slice(0, 40),
      d: b.d === 'm' ? 'm' : 'd'
    };
    registarMedicao(k, evento).catch(() => {});
  } catch (e) { /* nunca falha para o visitante */ }
});
// Mensagens do formulário de contacto contam no servidor (não dependem do script)
function medirContactoFormulario(site) {
  const k = chaveMedicaoDoSite(site || {});
  if (k) registarMedicao(k, { t: 'c', x: 'form' }).catch(() => {});
}

// ---- Pôr o script nos sites que já existiam antes desta versão ----
const estActivados = new Set();
async function activarMedicaoSite(site) {
  const k = chaveMedicaoDoSite(site);
  if (!k || estActivados.has(site._id) || site['Status'] !== 'Pronto') return false;
  estActivados.add(site._id);
  const caminho = String(site['Bunny Path'] || '').replace(/^\/+/, '');
  let ini;
  try { ini = (await descarregarDoBunny(caminho)).toString('utf8'); } catch (e) { return false; }
  if (/dia-medir\.js/.test(ini)) return false;
  const pasta = caminho.replace(/[^/]+$/, '');
  const cdnPasta = String(site['CDN URL'] || '').replace(/[^/]+$/, '');
  const ficheiros = ['index.html'].concat(String(metaDoHtml(ini, 'daniel-ia-paginas') || '').split(/\s+/).filter(f => /^[A-Za-z0-9_.-]{1,60}\.html$/.test(f) && f !== 'index.html'));
  for (const f of ficheiros) {
    try {
      const html = f === 'index.html' ? ini : (await descarregarDoBunny(pasta + f)).toString('utf8');
      if (/dia-medir\.js/.test(html)) continue;
      await uploadParaBunny(pasta + f, Buffer.from(html, 'utf8'), 'text/html; charset=utf-8');
      if (cdnPasta) await purgeCacheBunny(cdnPasta + f);
      if (site['Dominio Personalizado'] && site['Dominio Estado'] === 'Activo') {
        await purgeCacheBunny('https://' + site['Dominio Personalizado'] + '/' + (f === 'index.html' ? '' : f));
      }
    } catch (e) { /* página que não existe: segue */ }
  }
  return true;
}

// ---- Painel: visitas + encomendas, prontas para os gráficos ----
const estNomesProdutos = new Map();
async function nomeProduto(id) {
  if (estNomesProdutos.has(id)) return estNomesProdutos.get(id);
  let nome = '';
  try { const p = await bubbleGet('produto', id); nome = (p && p['Nome']) || ''; } catch (e) { nome = ''; }
  estNomesProdutos.set(id, nome);
  if (estNomesProdutos.size > 5000) estNomesProdutos.clear();
  return nome;
}
async function lerMesEst(k, mes) {
  const e = entradaEst(k, mes);
  await e.pronto;
  return e.doc;
}
function topLista(obj, n) {
  return Object.keys(obj || {}).map(nome => ({ nome, n: obj[nome] })).sort((a, b) => b.n - a.n).slice(0, n);
}
app.post('/estatisticas', async (req, res) => {
  try {
    const owner = req.body.owner;
    const dias = EST_DIAS_PERMITIDOS.includes(Number(req.body.dias)) ? Number(req.body.dias) : 30;
    const resumo = req.body.resumo === true;
    const todosSites = await bubbleListTodos('site', [{ key: 'Owner', constraint_type: 'equals', value: owner }], 500);
    const prontos = todosSites.filter(s => s['Status'] === 'Pronto');
    const pedido = String(req.body.site_id || 'todos');
    const escolhidos = pedido === 'todos' ? prontos : prontos.filter(s => s._id === pedido);
    if (pedido !== 'todos' && !escolhidos.length) return res.json({ status: 'error', message: 'Site não encontrado.' });

    // os sites antigos passam a medir a partir de agora (em fundo)
    escolhidos.forEach(s => { activarMedicaoSite(s).catch(() => {}); });

    const hoje = diaMaputo();
    const inicio = somarDias(hoje, -(dias - 1));
    const inicioAnt = somarDias(inicio, -dias);
    const listaDias = [];
    for (let d = inicio; d <= hoje; d = somarDias(d, 1)) listaDias.push(d);
    const meses = new Set();
    for (let d = inicioAnt; d <= hoje; d = somarDias(d, 1)) meses.add(d.slice(0, 7));

    // visitas
    const porDia = {};
    const ant = { v: 0, u: 0, w: 0, c: 0 };
    const tot = diaVazio();
    let temDados = false;
    for (const s of escolhidos) {
      const k = chaveMedicaoDoSite(s);
      if (!k) continue;
      for (const mes of meses) {
        const doc = await lerMesEst(k, mes);
        Object.keys(doc.dias || {}).forEach(dia => {
          const x = doc.dias[dia];
          temDados = true;
          if (dia >= inicio && dia <= hoje) {
            const a = porDia[dia] || (porDia[dia] = { v: 0, u: 0 });
            a.v += x.v || 0; a.u += x.u || 0;
            somarDia({ dias: { t: tot } }, 't', x);
          } else if (dia >= inicioAnt && dia < inicio) {
            ant.v += x.v || 0; ant.u += x.u || 0; ant.w += x.w || 0; ant.c += x.c || 0;
          }
        });
      }
    }

    // encomendas (lojas e páginas de venda)
    const vendasDia = {};
    const vendidos = {};
    let encomendas = 0, valor = 0, pago = 0, pendentes = 0, encAnt = 0, valorAnt = 0;
    const lojas = escolhidos.filter(s => s['Tipo'] === 'E-commerce' || s['Tipo'] === 'Checkout');
    for (const s of lojas) {
      const lista = await bubbleListTodos('encomenda', [{ key: 'Site', constraint_type: 'equals', value: s._id }], 3000).catch(() => []);
      lista.forEach(enc => {
        const dia = diaMaputo(new Date(enc['Created Date'] || 0).getTime());
        const v = Number(enc['Valor Total']) || 0;
        const estado = String(enc['Estado'] || '');
        if (/cancel|falh|expir/i.test(estado)) return;
        if (dia >= inicio && dia <= hoje) {
          encomendas++; valor += v;
          if (estado === 'Pago') pago += v;
          if (estado === 'Pendente' || estado === 'Aguarda pagamento') pendentes++;
          const a = vendasDia[dia] || (vendasDia[dia] = { valor: 0, n: 0 });
          a.valor += v; a.n++;
          if (!resumo) {
            let itens = [];
            try { itens = JSON.parse(enc['Produtos Json'] || '[]'); } catch (e) { itens = []; }
            (Array.isArray(itens) ? itens : []).slice(0, 50).forEach(it => {
              const nome = String(it.nome || 'Produto').slice(0, 80);
              const x = vendidos[nome] || (vendidos[nome] = { nome, qtd: 0, valor: 0 });
              x.qtd += Number(it.quantidade) || 1;
              x.valor += (Number(it.preco_unitario) || 0) * (Number(it.quantidade) || 1);
            });
          }
        } else if (dia >= inicioAnt && dia < inicio) {
          encAnt++; valorAnt += v;
        }
      });
    }

    const serie = listaDias.map(dia => ({
      dia,
      visitas: (porDia[dia] && porDia[dia].v) || 0,
      visitantes: (porDia[dia] && porDia[dia].u) || 0,
      vendas: (vendasDia[dia] && vendasDia[dia].valor) || 0,
      encomendas: (vendasDia[dia] && vendasDia[dia].n) || 0
    }));
    const resposta = {
      dias, inicio, fim: hoje, a_comecar: !temDados,
      tem_loja: lojas.length > 0,
      sites: prontos.map(s => ({ id: s._id, nome: s['Nome'] || 'Site', tipo: s['Tipo'] || '' })),
      totais: {
        visitas: tot.v, visitantes: tot.u, whatsapp: tot.w, contactos: tot.c,
        encomendas, valor, pago, pendentes,
        conversao: tot.u ? Math.round((encomendas / tot.u) * 1000) / 10 : 0
      },
      anteriores: { visitas: ant.v, visitantes: ant.u, whatsapp: ant.w, contactos: ant.c, encomendas: encAnt, valor: valorAnt },
      serie
    };
    if (!resumo) {
      resposta.origens = topLista(tot.o, 12);
      resposta.dispositivos = { telemovel: tot.d.m || 0, computador: tot.d.d || 0 };
      resposta.paginas = topLista(tot.p, 10);
      resposta.contactos = { whatsapp: tot.w, telefone: (tot.ct && tot.ct.tel) || 0, email: (tot.ct && tot.ct.mail) || 0, formulario: (tot.ct && tot.ct.form) || 0 };
      const vistos = topLista(tot.pr, 8);
      for (const x of vistos) x.nome = (await nomeProduto(x.nome)) || 'Produto removido';
      resposta.produtos_vistos = vistos;
      resposta.produtos_vendidos = Object.values(vendidos).sort((a, b) => b.valor - a.valor || b.qtd - a.qtd).slice(0, 8);
    }
    return res.json({ status: 'success', response: resposta });
  } catch (erro) {
    console.error('Erro em /estatisticas:', erro.message || erro);
    return res.json({ status: 'error', message: 'Não foi possível ler as estatísticas.' });
  }
});

ROTAS_PRIVADAS.add('/estatisticas');
Object.assign(LIMITES, {
  '/m': [['ip', 300, MIN]],
  '/estatisticas': [['owner', 120, 10 * MIN]]
});

// ======================================================
// Levantamentos dos donos de lojas - B2C MozPayment /wf/payout (1.63.0)
// ------------------------------------------------------
// - Só para contas habilitadas no painel (config/levantamentos.json no Bunny).
// - Saldo = encomendas pagas online (M-Pesa, e-Mola, cartão) pelas lojas da
//   pessoa, menos a comissão configurada, menos os levantamentos já feitos ou
//   em curso.
// - O payout é instantâneo: não há webhook. O estado vem da própria resposta.
//   Resposta ambígua ou sem resposta = "Pendente": o saldo fica reservado e o
//   admin confirma à mão no painel (nunca repetimos sozinhos -> sem duplicados).
// - Registos no tipo "levantamento" do Bubble: Owner, Valor MZN, Telefone,
//   Titular, Metodo, Estado, Referencia, Resposta.
// - O secret_id (MOZPAYMENT_SECRET_ID) só existe aqui no container.
// ======================================================
const MOZPAYMENT_SECRET_ID = clean(process.env.MOZPAYMENT_SECRET_ID);
const LEV_PADRAO = { minimo: 100, maximo: 50000, comissao: 0, contas: {} };
let cacheConfigLev = null;
async function configLevantamentos() {
  if (cacheConfigLev && Date.now() - cacheConfigLev.t < 30000) return cacheConfigLev.c;
  let c = JSON.parse(JSON.stringify(LEV_PADRAO));
  try {
    const g = JSON.parse((await descarregarDoBunny('config/levantamentos.json')).toString('utf8'));
    if (g && typeof g === 'object') {
      if (Number(g.minimo) >= 0) c.minimo = Number(g.minimo);
      if (Number(g.maximo) > 0) c.maximo = Number(g.maximo);
      if (Number(g.comissao) >= 0) c.comissao = Math.min(50, Number(g.comissao));
      if (g.contas && typeof g.contas === 'object') c.contas = g.contas;
    }
  } catch (e) { /* ainda não há configuração */ }
  cacheConfigLev = { t: Date.now(), c };
  return c;
}
async function guardarConfigLevantamentos(c) {
  await uploadParaBunny('config/levantamentos.json', Buffer.from(JSON.stringify(c), 'utf8'), 'application/json; charset=utf-8');
  cacheConfigLev = { t: Date.now(), c };
}
const ESTADOS_RESERVAM = ['A processar', 'Pendente', 'Pago'];
async function saldoLevantamentos(owner, cfg) {
  cfg = cfg || await configLevantamentos();
  const sites = await bubbleListTodos('site', [{ key: 'Owner', constraint_type: 'equals', value: owner }], 500).catch(() => []);
  const lojas = sites.filter(s => s['Tipo'] === 'E-commerce' || s['Tipo'] === 'Checkout');
  let vendido = 0, encomendas = 0;
  for (const s of lojas) {
    const l = await bubbleListTodos('encomenda', [{ key: 'Site', constraint_type: 'equals', value: s._id }], 5000).catch(() => []);
    l.forEach(e => {
      if (e['Estado'] !== 'Pago' || !['mpesa', 'emola', 'cartao'].includes(e['Metodo'])) return;
      if (String(e['Transaction ID'] || '').indexOf('admin:') === 0) return; // marcadas à mão no painel: o dinheiro não passou por nós
      vendido += Number(e['Valor Total']) || 0; encomendas++;
    });
  }
  const levs = await bubbleListTodos('levantamento', [{ key: 'Owner', constraint_type: 'equals', value: owner }], 2000).catch(() => []);
  let levantado = 0, emCurso = 0;
  levs.forEach(x => {
    const v = Number(x['Valor MZN']) || 0;
    if (x['Estado'] === 'Pago') levantado += v;
    else if (ESTADOS_RESERVAM.includes(x['Estado'])) emCurso += v;
  });
  const liquido = Math.floor(vendido * (1 - cfg.comissao / 100));
  const disponivel = Math.max(0, Math.floor(liquido - levantado - emCurso));
  levs.sort((a, b) => String(b['Created Date'] || '').localeCompare(String(a['Created Date'] || '')));
  return { vendido, encomendas, comissao: cfg.comissao, liquido, levantado, em_curso: emCurso, disponivel, lojas: lojas.length, historico: levs };
}
function levantamentoPublico(x) {
  return { id: x._id, valor: Number(x['Valor MZN']) || 0, telefone: x['Telefone'] || '', titular: x['Titular'] || '', metodo: x['Metodo'] || '',
    estado: x['Estado'] || '', referencia: x['Referencia'] || '', criado: x['Created Date'] || '', owner: x['Owner'] || '' };
}
// Lê o resultado do payout. Só "Pago" com sinal claro de sucesso; erro claro = "Falhou";
// o resto fica "Pendente" para confirmar à mão.
function estadoDoPayout(r) {
  const j = r.json && typeof r.json === 'object' ? r.json : {};
  const valores = [j.status, j.state, j.result, j.message, j.response && j.response.status, j.response && j.response.state, j.data && j.data.status]
    .filter(v => v != null).map(v => String(v).trim().toLowerCase());
  const ok = ['success', 'successful', 'completed', 'paid', 'sucesso', 'approved', 'concluido', 'pago'];
  const mau = ['error', 'erro', 'failed', 'fail', 'falhou', 'rejected', 'recusad', 'declined', 'cancelled', 'canceled', 'insufficient', 'insuficiente', 'invalid', 'invalido', 'inválido'];
  if (!r.ok || valores.some(v => mau.some(m => v.indexOf(m) >= 0)) || j.error || j.errors) return 'Falhou';
  if (valores.some(v => ok.includes(v))) return 'Pago';
  return 'Pendente';
}
function referenciaDoPayout(j) {
  j = j && typeof j === 'object' ? j : {};
  const r = j.response && typeof j.response === 'object' ? j.response : {};
  return String(j.transaction_id || j.reference || j.id || j.payout_id || r.transaction_id || r.reference || r.id || r.payout_id || '').slice(0, 120);
}
function semSegredo(texto) {
  let t = String(texto || '');
  if (MOZPAYMENT_SECRET_ID) t = t.split(MOZPAYMENT_SECRET_ID).join('***');
  return t.slice(0, 1500);
}
const levEmCurso = new Set();

app.post('/levantamentos', async (req, res) => {
  try {
    const owner = req.body.owner;
    const cfg = await configLevantamentos();
    const conta = cfg.contas[owner];
    const s = await saldoLevantamentos(owner, cfg);
    const user = await bubbleGet('user', owner).catch(() => null);
    return res.json({ status: 'success', response: {
      habilitado: !!(conta && conta.activo), kyc: await kycAprovado(owner),
      minimo: cfg.minimo, maximo: Math.min(cfg.maximo, Number(conta && conta.maximo) > 0 ? Number(conta.maximo) : cfg.maximo),
      saldo: { vendido: s.vendido, encomendas: s.encomendas, comissao: s.comissao, liquido: s.liquido, levantado: s.levantado, em_curso: s.em_curso, disponivel: s.disponivel },
      titular_sugerido: (user && user['Full Name']) || '',
      historico: s.historico.slice(0, 50).map(levantamentoPublico)
    } });
  } catch (erro) {
    console.error('Erro em /levantamentos:', erro.message || erro);
    return res.json({ status: 'error', message: 'Não foi possível ler o teu saldo.' });
  }
});

app.post('/levantamento-pedir', async (req, res) => {
  const owner = req.body.owner;
  if (levEmCurso.has(owner)) return res.json({ status: 'error', message: 'Já tens um levantamento a ser processado. Espera uns segundos.' });
  levEmCurso.add(owner);
  let registoId = '';
  try {
    if (!MOZPAYMENT_SECRET_ID || !MOZPAYMENT_WALLET) {
      return res.json({ status: 'error', message: 'Os levantamentos ainda não estão configurados. Fala connosco.' });
    }
    const cfg = await configLevantamentos();
    const conta = cfg.contas[owner];
    if (!conta || !conta.activo) return res.json({ status: 'error', codigo: 'nao-habilitado', message: 'Os levantamentos ainda não estão activos na tua conta. Fala connosco.' });
    if (!(await kycAprovado(owner))) return res.json({ status: 'error', message: 'Precisas da identidade verificada (KYC) para levantar dinheiro.' });
    const metodo = String(req.body.metodo || '');
    if (!['mpesa', 'emola'].includes(metodo)) return res.json({ status: 'error', message: 'Escolhe M-Pesa ou e-Mola.' });
    let numero;
    try { numero = validarNumeroOperadora(req.body.telefone, metodo); } catch (e) { return res.json({ status: 'error', message: e.publico || 'Número inválido.' }); }
    const titular = String(req.body.titular || '').replace(/\s+/g, ' ').trim().slice(0, 80);
    if (titular.split(' ').length < 2) return res.json({ status: 'error', message: 'Escreve o nome completo do titular do número.' });
    const valor = Math.floor(Number(req.body.valor));
    const maximo = Math.min(cfg.maximo, Number(conta.maximo) > 0 ? Number(conta.maximo) : cfg.maximo);
    if (!(valor > 0)) return res.json({ status: 'error', message: 'Escreve o valor a levantar.' });
    if (valor < cfg.minimo) return res.json({ status: 'error', message: 'O valor mínimo por levantamento é ' + cfg.minimo + ' MZN.' });
    if (valor > maximo) return res.json({ status: 'error', message: 'O valor máximo por levantamento é ' + maximo + ' MZN.' });
    const s = await saldoLevantamentos(owner, cfg);
    if (valor > s.disponivel) return res.json({ status: 'error', message: 'Só tens ' + s.disponivel + ' MZN disponíveis para levantar.' });

    // 1. reservar o valor antes de pedir (se o servidor cair a meio, o saldo não fica livre para levantar outra vez)
    registoId = await bubbleCreate('levantamento', {
      'Owner': owner, 'Valor MZN': valor, 'Telefone': numero, 'Titular': titular, 'Metodo': metodo,
      'Estado': 'A processar', 'Referencia': '', 'Resposta': ''
    });
    // 2. pedir o envio
    let r;
    try {
      r = await chamarMozpayment('payout', {
        phone: numero, holder: titular, method: metodo, amount: String(valor),
        wallet: MOZPAYMENT_WALLET, secret_id: MOZPAYMENT_SECRET_ID
      });
    } catch (e) {
      // sem resposta: não sabemos se saiu -> Pendente (o admin confirma), nunca repetir sozinho
      await bubblePatch('levantamento', registoId, { 'Estado': 'Pendente', 'Resposta': semSegredo('sem resposta: ' + (e.message || e)) }).catch(() => {});
      avisarAdminLevantamento(owner, valor, numero, 'Pendente', 'sem resposta da MozPayment');
      return res.json({ status: 'success', response: { estado: 'Pendente', id: registoId, valor } });
    }
    const estado = estadoDoPayout(r);
    const referencia = referenciaDoPayout(r.json);
    await bubblePatch('levantamento', registoId, { 'Estado': estado, 'Referencia': referencia, 'Resposta': semSegredo(r.texto) });
    console.log('[levantamento]', owner, valor, metodo, '->', estado, referencia);
    if (estado !== 'Pago') avisarAdminLevantamento(owner, valor, numero, estado, semSegredo(r.texto).slice(0, 300));
    if (estado === 'Pago') avisarDonoLevantamento(owner, valor, numero, metodo);
    return res.json({ status: estado === 'Falhou' ? 'error' : 'success', message: estado === 'Falhou' ? 'O envio não foi aceite pela operadora. O valor continua no teu saldo.' : undefined,
      response: { estado, id: registoId, valor, referencia } });
  } catch (erro) {
    console.error('Erro em /levantamento-pedir:', erro.message || erro);
    if (registoId) await bubblePatch('levantamento', registoId, { 'Estado': 'Pendente', 'Resposta': semSegredo('erro interno: ' + (erro.message || erro)) }).catch(() => {});
    return res.json({ status: 'error', message: 'Não foi possível pedir o levantamento. Tenta outra vez daqui a pouco.' });
  } finally {
    levEmCurso.delete(owner);
  }
});

function avisarAdminLevantamento(owner, valor, numero, estado, nota) {
  try {
    if (!ADMIN_EMAIL) return;
    enviarEmail(ADMIN_EMAIL, 'Levantamento ' + estado + ' - ' + valor + ' MZN',
      '<p>Levantamento de <b>' + valor + ' MZN</b> para <b>' + escaparHtml(numero) + '</b> (conta ' + escaparHtml(owner) + ') ficou <b>' + escaparHtml(estado) + '</b>.</p><p>' + escaparHtml(nota || '') + '</p><p>Confirma no painel: Levantamentos.</p>').catch(() => {});
  } catch (e) { /* aviso não pode falhar o levantamento */ }
}
async function avisarDonoLevantamento(owner, valor, numero, metodo) {
  try {
    const u = await bubbleGet('user', owner);
    const email = emailDoUsuario(u);
    if (!email) return;
    await enviarEmail(email, 'Levantamento enviado: ' + valor + ' MZN',
      '<p>Enviámos <b>' + valor + ' MZN</b> para o teu ' + (metodo === 'mpesa' ? 'M-Pesa' : 'e-Mola') + ' <b>' + escaparHtml(numero) + '</b>.</p><p>Obrigado por vender com a Daniel IA.</p>');
  } catch (e) { /* sem email não faz mal */ }
}

// ---- Painel de administração ----
app.post('/admin-levantamentos', async (req, res) => {
  try {
    if (!(await exigirAdmin(req, res))) return;
    const cfg = await configLevantamentos();
    const lista = await bubbleListTodos('levantamento', [], 3000).catch(() => []);
    lista.sort((a, b) => String(b['Created Date'] || '').localeCompare(String(a['Created Date'] || '')));
    const nomes = {};
    for (const id of Object.keys(cfg.contas)) {
      const u = await bubbleGet('user', id).catch(() => null);
      nomes[id] = u ? ((u['Full Name'] || '') + ' · ' + (emailDoUsuario(u) || '')) : id;
    }
    return res.json({ status: 'success', response: {
      configurado: !!(MOZPAYMENT_SECRET_ID && MOZPAYMENT_WALLET), modo_c2b: PAGAMENTOS_MOVEL,
      config: { minimo: cfg.minimo, maximo: cfg.maximo, comissao: cfg.comissao },
      contas: Object.keys(cfg.contas).map(id => Object.assign({ id, nome: nomes[id] }, cfg.contas[id])),
      levantamentos: lista.slice(0, 300).map(levantamentoPublico)
    } });
  } catch (erro) {
    return res.json({ status: 'error', message: 'Não foi possível ler os levantamentos.' });
  }
});
app.post('/admin-levantamentos-config', async (req, res) => {
  try {
    const admin = await exigirAdmin(req, res);
    if (!admin) return;
    const cfg = JSON.parse(JSON.stringify(await configLevantamentos()));
    const b = req.body;
    if (b.config) {
      if (Number(b.config.minimo) >= 0) cfg.minimo = Math.floor(Number(b.config.minimo));
      if (Number(b.config.maximo) > 0) cfg.maximo = Math.floor(Number(b.config.maximo));
      if (Number(b.config.comissao) >= 0) cfg.comissao = Math.min(50, Number(b.config.comissao));
    }
    if (b.user_id) {
      const u = await bubbleGet('user', b.user_id).catch(() => null);
      if (!u) return res.json({ status: 'error', message: 'Conta não encontrada.' });
      cfg.contas[b.user_id] = Object.assign({}, cfg.contas[b.user_id] || {}, {
        activo: !!b.activo, maximo: Number(b.maximo) > 0 ? Math.floor(Number(b.maximo)) : null, mudado: new Date().toISOString()
      });
    }
    await guardarConfigLevantamentos(cfg);
    registar(admin, 'levantamentos-config', b.user_id ? (b.user_id + ' ' + (b.activo ? 'ligado' : 'desligado')) : JSON.stringify(b.config || {}));
    return res.json({ status: 'success', response: { config: { minimo: cfg.minimo, maximo: cfg.maximo, comissao: cfg.comissao }, conta: b.user_id ? cfg.contas[b.user_id] : null } });
  } catch (erro) {
    return res.json({ status: 'error', message: 'Não foi possível guardar.' });
  }
});
app.post('/admin-levantamento-saldo', async (req, res) => {
  try {
    if (!(await exigirAdmin(req, res))) return;
    const cfg = await configLevantamentos();
    const s = await saldoLevantamentos(req.body.user_id, cfg);
    return res.json({ status: 'success', response: { habilitado: !!(cfg.contas[req.body.user_id] && cfg.contas[req.body.user_id].activo), conta: cfg.contas[req.body.user_id] || null,
      saldo: { vendido: s.vendido, liquido: s.liquido, levantado: s.levantado, em_curso: s.em_curso, disponivel: s.disponivel }, historico: s.historico.slice(0, 10).map(levantamentoPublico) } });
  } catch (erro) {
    return res.json({ status: 'error', message: 'Não foi possível ler o saldo.' });
  }
});
// Confirmar à mão um levantamento Pendente (depois de ver na MozPayment se saiu ou não).
app.post('/admin-levantamento-estado', async (req, res) => {
  try {
    const admin = await exigirAdmin(req, res);
    if (!admin) return;
    const novo = req.body.estado;
    if (!['Pago', 'Falhou'].includes(novo)) return res.json({ status: 'error', message: 'Estado inválido.' });
    const x = await bubbleGet('levantamento', req.body.levantamento_id).catch(() => null);
    if (!x) return res.json({ status: 'error', message: 'Levantamento não encontrado.' });
    if (!['Pendente', 'A processar'].includes(x['Estado'])) return res.json({ status: 'error', message: 'Só dá para mudar levantamentos pendentes.' });
    await bubblePatch('levantamento', x._id, { 'Estado': novo, 'Resposta': semSegredo((x['Resposta'] || '') + ' | ' + novo + ' à mão por ' + (emailDoUsuario(admin) || 'admin')) });
    registar(admin, 'levantamento-' + novo.toLowerCase(), x._id + ' ' + x['Valor MZN'] + ' MZN');
    if (novo === 'Pago') avisarDonoLevantamento(x['Owner'], x['Valor MZN'], x['Telefone'], x['Metodo']);
    return res.json({ status: 'success', response: { estado: novo } });
  } catch (erro) {
    return res.json({ status: 'error', message: 'Não foi possível mudar.' });
  }
});

['/levantamentos', '/levantamento-pedir', '/admin-levantamentos', '/admin-levantamentos-config', '/admin-levantamento-saldo', '/admin-levantamento-estado']
  .forEach(r => ROTAS_PRIVADAS.add(r));
Object.assign(LIMITES, {
  '/levantamento-pedir': [['owner', 20, 60 * MIN]],
  '/levantamentos': [['owner', 120, 10 * MIN]]
});

app.listen(PORT, () => {
  console.log(`daniel-ia-proxy v${VERSION} a correr na porta ${PORT}`);
});
